import { defineConfig } from 'vite'

export default defineConfig({
  base: './',
  build: { outDir: 'dist', assetsInlineLimit: 0 },
})

@import url('https://fonts.googleapis.com/css2?family=Nunito:wght@600;700;800;900&family=Teko:wght@600;700&display=swap');

:root {
  --ink: #0b1322;
  --panel: #162238;
  --panel-2: #1d2c47;
  --line: #3b5175;
  --mint: #5ce1b9;
  --yellow: #ffd447;
  --orange: #ff8a3d;
  --red: #ff5364;
  --blue: #4aa8ff;
  --text: #f2f7ff;
  --muted: #9fb0cb;
  --font: 'Nunito', 'Trebuchet MS', 'Arial Rounded MT Bold', system-ui, sans-serif;
  --display: 'Teko', 'Arial Narrow', Impact, sans-serif;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; height: 100%; overflow: hidden; background: #0a111e; color: var(--text); font-family: var(--font); }
body { user-select: none; }
button { font-family: inherit; cursor: pointer; }
.hidden { display: none !important; }
#app { position: fixed; inset: 0; }
#gameCanvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }

/* ---------- shared UI atoms ---------- */
.screen, .overlay { position: absolute; inset: 0; z-index: 10; }
.overlay { background: rgba(6, 11, 20, .74); backdrop-filter: blur(8px); display: grid; place-items: center; padding: 18px; z-index: 30; }
.btn {
  border: 2px solid rgba(255,255,255,.16); background: linear-gradient(180deg, #2a3b5c, #1b2942);
  color: #fff; font-weight: 900; letter-spacing: .06em; border-radius: 12px; padding: 13px 22px;
  box-shadow: 0 5px 0 #0a1220, 0 10px 24px #0005; transition: transform .11s, filter .11s, box-shadow .11s;
  font-size: 14px; text-shadow: 0 2px 2px #0004;
}
.btn:hover { transform: translateY(-2px); filter: brightness(1.13); box-shadow: 0 7px 0 #0a1220, 0 14px 28px #0006; }
.btn:active { transform: translateY(3px); box-shadow: 0 2px 0 #0a1220; }
.btn-primary { background: linear-gradient(180deg, #ffdf5e, #ffae2e); color: #402400; border-color: #fff2ae; box-shadow: 0 5px 0 #a56009, 0 10px 24px #0006; text-shadow: none; }
.btn-primary:hover { box-shadow: 0 7px 0 #a56009, 0 14px 28px #0006; }
.btn-primary:active { box-shadow: 0 2px 0 #a56009; }
.btn-lg { padding: 16px 26px; font-size: 16px; min-width: 190px; }
.btn-ghost { background: transparent; border-color: #ffffff38; box-shadow: none; color: var(--muted); }
.btn-ghost:hover { color: #fff; box-shadow: none; }
.btn small { display: block; font-size: 9px; letter-spacing: .18em; opacity: .7; font-weight: 800; margin-top: 2px; }
.pill { display: flex; align-items: center; gap: 8px; background: #0d1728cc; border: 2px solid #ffffff1c; border-radius: 999px; padding: 8px 14px; font-weight: 900; font-size: 11px; letter-spacing: .08em; }
.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--mint); box-shadow: 0 0 10px var(--mint); animation: pulse 2s infinite; }
@keyframes pulse { 50% { opacity: .45; } }
.coin-icon { color: var(--yellow); font-size: 15px; }

/* ---------- loading ---------- */
#loading { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 18px; background: radial-gradient(circle at 50% 35%, #223a5b, #0a111e 70%); }
.loader-logo { display: flex; align-items: center; gap: 14px; font-family: var(--display); font-size: 44px; letter-spacing: .06em; }
.cube, .brand-mark { display: grid; place-items: center; width: 46px; height: 46px; border-radius: 10px; background: linear-gradient(145deg, #ffe275, #ff9f1c); color: #4a2900; font-family: var(--display); font-size: 34px; box-shadow: inset -5px -5px 0 #c96e00, inset 4px 4px 0 #fff3b0; }
.loader-bar { width: 220px; height: 9px; background: #ffffff18; border-radius: 9px; overflow: hidden; }
.loader-bar i { display: block; height: 100%; width: 35%; border-radius: 9px; background: linear-gradient(90deg, var(--mint), var(--yellow)); animation: load 1.1s ease-in-out infinite; }
@keyframes load { 0% { transform: translateX(-110%); } 100% { transform: translateX(330%); } }
#loading p { color: var(--muted); font-weight: 800; letter-spacing: .1em; font-size: 12px; }

/* ---------- main menu ---------- */
#menu { background: linear-gradient(90deg, rgba(7,13,24,.94) 0%, rgba(7,13,24,.78) 40%, rgba(7,13,24,.06) 72%); display: flex; flex-direction: column; padding: clamp(16px, 3vw, 36px) clamp(18px, 5vw, 76px); }
.menu-nav { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.brand { display: flex; align-items: center; gap: 12px; font-family: var(--display); font-size: 26px; letter-spacing: .045em; }
.brand em { font-style: normal; color: var(--yellow); }
.nav-right { display: flex; gap: 10px; }
.menu-hero { flex: 1; display: flex; align-items: center; justify-content: space-between; gap: 30px; max-width: 1240px; width: 100%; margin: 0 auto; }
.hero-copy { max-width: 600px; }
.eyebrow { display: inline-block; color: var(--mint); font-weight: 900; letter-spacing: .22em; font-size: 11px; margin-bottom: 12px; }
.hero-copy h1 { font-family: var(--display); font-size: clamp(56px, 8.4vw, 118px); line-height: .82; letter-spacing: -.01em; margin: 0 0 20px; text-transform: uppercase; text-shadow: 0 6px 0 #0006, 0 12px 30px #0007; }
.hero-copy h1 span { color: var(--yellow); }
.hero-desc { color: #c5d4e9; font-size: clamp(13px, 1.2vw, 16px); line-height: 1.6; max-width: 500px; margin: 0 0 26px; font-weight: 700; }
.hero-buttons { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
.hero-stats { display: flex; gap: 30px; margin-top: 34px; }
.hero-stats div { display: flex; flex-direction: column; }
.hero-stats b { font-family: var(--display); font-size: 32px; line-height: 1; color: #fff; }
.hero-stats span { font-size: 9px; font-weight: 900; letter-spacing: .16em; color: var(--muted); margin-top: 5px; }
.hero-card { position: relative; width: 260px; flex-shrink: 0; border: 3px solid #ffffff24; border-radius: 22px; padding: 18px; background: linear-gradient(170deg, #172944e8, #0d1728e8); box-shadow: 0 25px 60px #0008, inset 0 1px #ffffff20; }
.card-tag { position: absolute; top: -13px; left: 18px; background: var(--yellow); color: #4a2900; font-size: 10px; font-weight: 900; letter-spacing: .14em; padding: 5px 12px; border-radius: 6px; }
.loadout-avatar { position: relative; height: 190px; margin: 8px 0 12px; background: radial-gradient(circle at 50% 70%, #3b5a7d66, transparent 65%); }
.block-head { position: absolute; top: 26px; left: 50%; transform: translateX(-50%); width: 58px; height: 54px; background: #ffd8a8; border: 3px solid #7a4e2b; border-radius: 6px; box-shadow: inset -6px -6px 0 #0002; z-index: 3; }
.block-head::before { content: ''; position: absolute; top: -16px; left: -3px; width: 58px; height: 16px; background: #e93b3b; border: 3px solid #7a1f1f; border-radius: 5px 5px 0 0; }
.block-head::after { content: ''; position: absolute; top: -21px; left: 18px; width: 16px; height: 8px; background: #e93b3b; border: 3px solid #7a1f1f; border-radius: 4px 4px 0 0; }
.block-head i { position: absolute; top: 18px; width: 9px; height: 12px; background: #fff; border: 2px solid #222; border-radius: 2px; }
.block-head i:first-child { left: 10px; } .block-head i:last-child { right: 10px; }
.block-body { position: absolute; top: 84px; left: 50%; transform: translateX(-50%); width: 62px; height: 62px; background: #ffcf33; border: 3px solid #a87900; border-radius: 6px; z-index: 2; }
.block-arms { position: absolute; top: 88px; left: 50%; transform: translateX(-50%); width: 104px; height: 44px; background: linear-gradient(90deg, #ffcf33 0 18px, transparent 18px calc(100% - 18px), #ffcf33 calc(100% - 18px)); z-index: 1; }
.block-legs { position: absolute; top: 148px; left: 50%; transform: translateX(-50%); width: 56px; height: 40px; background: linear-gradient(90deg, #2f6fd0 0 24px, transparent 24px 32px, #2f6fd0 32px); border-radius: 3px; }
.loadout-name { font-family: var(--display); font-size: 26px; line-height: 1; }
.loadout-sub { color: var(--mint); font-size: 11px; font-weight: 900; letter-spacing: .05em; margin-top: 5px; }
.loadout-bar { height: 6px; background: #ffffff18; border-radius: 6px; margin-top: 14px; overflow: hidden; }
.loadout-bar i { display: block; height: 100%; width: 72%; background: linear-gradient(90deg, var(--mint), var(--blue)); }
.menu-footer { display: flex; justify-content: space-between; gap: 14px; color: #8fa2bf; font-size: 10px; font-weight: 900; letter-spacing: .1em; flex-wrap: wrap; }
.footer-tag { color: var(--yellow); }

/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; pointer-events: none; z-index: 15; }
.hud-top { position: absolute; top: max(16px, env(safe-area-inset-top)); left: 50%; transform: translateX(-50%); display: flex; align-items: flex-start; gap: 22px; }
.match-info { background: #0b1525cc; border: 2px solid #ffffff1c; border-radius: 12px; padding: 8px 18px 10px; min-width: 130px; text-align: center; }
.match-tag { font-size: 9px; font-weight: 900; letter-spacing: .18em; color: var(--mint); }
.match-time { font-family: var(--display); font-size: 34px; line-height: 1; letter-spacing: .04em; }
.match-progress { height: 4px; background: #ffffff22; border-radius: 4px; margin-top: 5px; overflow: hidden; }
.match-progress i { display: block; height: 100%; width: 100%; background: var(--yellow); transition: width .4s linear; }
.top-score { display: flex; align-items: center; gap: 10px; background: #0b1525cc; border: 2px solid #ffffff1c; border-radius: 12px; padding: 8px 16px; }
.top-score > div { display: flex; flex-direction: column; align-items: center; }
.top-score span { font-size: 9px; font-weight: 900; letter-spacing: .14em; color: var(--muted); }
.top-score b { font-family: var(--display); font-size: 28px; line-height: 1; }
.score-you b { color: var(--yellow); } .score-sep { opacity: .4; font-size: 20px; }
.leaderboard { background: #0b1525cc; border: 2px solid #ffffff1c; border-radius: 12px; padding: 8px 12px; min-width: 150px; font-size: 11px; font-weight: 900; }
.lb-row { display: flex; justify-content: space-between; gap: 12px; padding: 2px 0; color: #cfdcf0; }
.lb-row.me { color: var(--yellow); } .lb-row span:last-child { font-family: var(--display); font-size: 15px; line-height: 1; }

.killfeed { position: absolute; top: 110px; right: 18px; display: flex; flex-direction: column; gap: 6px; align-items: flex-end; }
.kf-item { background: #0a1423e0; border: 2px solid #ffffff1c; border-left: 4px solid var(--red); border-radius: 8px; padding: 7px 12px; font-size: 11px; font-weight: 900; animation: kfIn .2s ease-out; }
.kf-item b { color: var(--yellow); } .kf-item i { color: #fff; font-style: normal; } .kf-item em { color: var(--red); font-style: normal; }
@keyframes kfIn { from { transform: translateX(30px); opacity: 0; } }
.crosshair { position: absolute; left: 50%; top: 50%; width: 34px; height: 34px; transform: translate(-50%, -50%); transition: transform .1s; }
.crosshair.scoped { transform: translate(-50%, -50%) scale(.35); }
.ch { position: absolute; background: #fff; box-shadow: 0 0 3px #000a; border-radius: 2px; }
.ch.top, .ch.bottom { width: 3px; height: 9px; left: 15.5px; }
.ch.top { top: 0; } .ch.bottom { bottom: 0; }
.ch.left, .ch.right { height: 3px; width: 9px; top: 15.5px; }
.ch.left { left: 0; } .ch.right { right: 0; }
.ch.dot { width: 3px; height: 3px; left: 15.5px; top: 15.5px; border-radius: 50%; }
.hitmarker { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%) scale(2); font-size: 26px; color: #fff; opacity: 0; text-shadow: 0 0 8px #ff5364; transition: opacity .08s, transform .08s; }
.hitmarker.show { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.hitmarker.head { color: var(--yellow); }
.scope-overlay { position: absolute; inset: 0; display: none; }
.scope-overlay.show { display: block; background: radial-gradient(circle at center, transparent 0 22vw, #000b 22.2vw 100%); }
.scope-overlay i:first-child { position: absolute; left: 50%; top: 0; bottom: 0; width: 2px; background: #000a; transform: translateX(-50%); }
.scope-overlay i:last-child { position: absolute; top: 50%; left: 0; right: 0; height: 2px; background: #000a; transform: translateY(-50%); }
.damage-vignette { position: absolute; inset: 0; background: radial-gradient(circle, transparent 45%, #ff244699 100%); opacity: 0; transition: opacity .35s; }
.low-health { position: absolute; inset: 0; background: radial-gradient(circle, transparent 55%, #ff000044 100%); opacity: 0; animation: lowPulse 1.2s infinite; }
@keyframes lowPulse { 50% { opacity: .75; } }
.kill-banner { position: absolute; left: 50%; top: 30%; transform: translate(-50%, -50%) scale(.7); text-align: center; opacity: 0; transition: opacity .18s, transform .18s; }
.kill-banner.show { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.kill-banner b { display: block; font-family: var(--display); font-size: 60px; line-height: .9; color: var(--yellow); text-shadow: 0 4px 0 #9c5500, 0 8px 20px #000a; letter-spacing: .04em; }
.kill-banner span { font-weight: 900; color: var(--mint); font-size: 14px; letter-spacing: .1em; }
.respawn { position: absolute; inset: 0; display: grid; place-items: center; background: #080e19aa; }
.respawn-card { text-align: center; background: #101c30ee; border: 3px solid #ffffff22; border-radius: 20px; padding: 28px 48px; box-shadow: 0 24px 60px #0009; }
.respawn-skull { font-size: 52px; } .respawn-title { font-family: var(--display); font-size: 46px; color: var(--red); line-height: 1; }
.respawn-sub { font-weight: 900; color: #dce7f8; margin-top: 6px; } .respawn-sub b { color: var(--yellow); font-size: 18px; }
.respawn-tip { color: var(--muted); font-size: 11px; margin-top: 14px; font-weight: 800; }

.hud-bottom { position: absolute; left: 0; right: 0; bottom: max(18px, env(safe-area-inset-bottom)); display: flex; justify-content: space-between; align-items: flex-end; padding: 0 clamp(14px, 3vw, 40px); gap: 18px; }
.health-panel { background: #0b1525dd; border: 2px solid #ffffff1c; border-radius: 12px; padding: 10px 16px; min-width: 190px; }
.hp-row { display: flex; align-items: baseline; gap: 6px; } .hp-icon { color: var(--mint); font-size: 18px; } .hp-row b { font-family: var(--display); font-size: 30px; line-height: 1; } .hp-max { color: var(--muted); font-weight: 800; font-size: 12px; }
.hp-bar { height: 9px; border-radius: 9px; background: #ffffff1c; overflow: hidden; margin-top: 6px; }
.hp-bar i { display: block; height: 100%; width: 100%; border-radius: 9px; background: linear-gradient(90deg, #35d39a, #8ef0b6); transition: width .15s; }
.hp-label { font-size: 9px; font-weight: 900; letter-spacing: .18em; color: var(--muted); margin-top: 5px; }
.weapon-slots { display: flex; gap: 8px; align-items: flex-end; }
.wslot { width: 74px; background: #0b1525cc; border: 2px solid #ffffff1c; border-radius: 10px; padding: 7px 6px; text-align: center; opacity: .65; transition: .15s; }
.wslot.active { opacity: 1; border-color: var(--yellow); background: #2b2a1ce8; transform: translateY(-5px); }
.wslot b { display: block; font-family: var(--display); font-size: 20px; line-height: 1; color: var(--yellow); }
.wslot span { display: block; font-size: 8px; font-weight: 900; letter-spacing: .03em; margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wslot i { display: block; height: 3px; margin: 5px 4px 0; background: #ffffff25; border-radius: 3px; overflow: hidden; }
.wslot i em { display: block; height: 100%; background: var(--mint); }
.ammo-panel { background: #0b1525dd; border: 2px solid #ffffff1c; border-radius: 12px; padding: 10px 18px; min-width: 190px; text-align: right; }
.ammo-name { font-family: var(--display); font-size: 24px; line-height: 1; }
.ammo-skin { font-size: 9px; font-weight: 900; letter-spacing: .14em; color: var(--mint); margin: 2px 0 4px; }
.ammo-row { display: flex; justify-content: flex-end; align-items: baseline; gap: 7px; }
.ammo-row b { font-family: var(--display); font-size: 42px; line-height: .9; }
.ammo-row span { font-family: var(--display); font-size: 22px; color: var(--muted); }
.reload-bar { height: 4px; border-radius: 4px; background: #ffffff1c; margin-top: 7px; overflow: hidden; opacity: 0; }
.reload-bar.show { opacity: 1; }
.reload-bar i { display: block; height: 100%; width: 0; background: var(--yellow); }
.reload-hint { font-size: 9px; font-weight: 900; letter-spacing: .12em; color: var(--muted); margin-top: 5px; }
.hud-hint { position: absolute; left: 50%; bottom: 4px; transform: translateX(-50%); font-size: 9px; font-weight: 900; letter-spacing: .1em; color: #ffffff66; white-space: nowrap; }
.pickup-toast { position: absolute; left: 50%; top: 62%; transform: translateX(-50%); color: var(--mint); font-weight: 900; letter-spacing: .1em; font-size: 15px; opacity: 0; transition: opacity .2s; text-shadow: 0 2px 6px #000; }
.pickup-toast.show { opacity: 1; }

/* ---------- modals ---------- */
.modal { width: min(980px, 100%); max-height: min(90vh, 820px); overflow: hidden; background: linear-gradient(160deg, #1a2942, #101a2c); border: 3px solid #ffffff24; border-radius: 20px; box-shadow: 0 30px 90px #000b, inset 0 1px #ffffff1e; display: flex; flex-direction: column; }
.modal-head { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 20px 26px; border-bottom: 2px solid #ffffff14; }
.modal-head h2 { font-family: var(--display); font-size: 40px; letter-spacing: .04em; margin: 0; line-height: 1; }
.modal-head p { margin: 6px 0 0; color: var(--muted); font-size: 12px; font-weight: 800; }
.modal-head > span { color: var(--muted); font-size: 11px; font-weight: 900; letter-spacing: .1em; }
.close-btn { background: #ffffff14; border: 2px solid #ffffff24; color: #fff; width: 38px; height: 38px; border-radius: 10px; font-size: 16px; font-weight: 900; }
.close-btn:hover { background: var(--red); }
.scoreboard-modal { width: min(720px, 100%); }
.score-table { padding: 14px 26px 20px; overflow-y: auto; }
.score-row { display: grid; grid-template-columns: 40px 1fr 80px 80px 80px; gap: 8px; padding: 9px 12px; border-radius: 8px; font-weight: 900; font-size: 13px; align-items: center; }
.score-row:not(.score-head):nth-child(odd) { background: #ffffff0b; }
.score-row.me { background: #ffd44720; color: var(--yellow); }
.score-head { color: var(--muted); font-size: 10px; letter-spacing: .14em; border-bottom: 2px solid #ffffff14; border-radius: 0; }
.score-row span:nth-child(n+3) { text-align: center; font-family: var(--display); font-size: 19px; }
.modal-foot { padding: 12px; text-align: center; color: var(--muted); font-size: 10px; font-weight: 900; letter-spacing: .12em; border-top: 2px solid #ffffff14; }
.cust-coins { margin-left: auto; display: flex; align-items: center; gap: 7px; background: #ffd44718; border: 2px solid #ffd44755; border-radius: 10px; padding: 7px 14px; }
.cust-coins span { color: var(--yellow); font-size: 18px; } .cust-coins b { color: var(--yellow); font-size: 18px; font-family: var(--display); } .cust-coins small { color: var(--muted); font-size: 9px; font-weight: 900; letter-spacing: .1em; }
.cust-tabs { display: flex; gap: 6px; padding: 14px 26px 0; }
.cust-tab { background: #ffffff0d; border: 2px solid transparent; color: var(--muted); border-radius: 9px 9px 0 0; padding: 10px 18px; font-weight: 900; font-size: 11px; letter-spacing: .1em; }
.cust-tab.active { background: #ffffff1a; color: var(--yellow); border-color: #ffffff24; border-bottom-color: transparent; }
.cust-body { display: flex; min-height: 0; flex: 1; padding: 0 26px 26px; gap: 20px; }
.preview-pane { width: 260px; flex-shrink: 0; background: radial-gradient(circle at 50% 60%, #35527a, #14203a 70%); border: 2px solid #ffffff1c; border-radius: 14px; display: flex; flex-direction: column; align-items: center; position: relative; overflow: hidden; }
#previewCanvas { width: 100%; height: 260px; display: block; }
.preview-label { font-family: var(--display); font-size: 28px; line-height: 1; letter-spacing: .04em; }
.preview-sub { color: var(--mint); font-size: 10px; font-weight: 900; letter-spacing: .14em; margin-bottom: 16px; text-transform: uppercase; }
.skin-pane { flex: 1; overflow-y: auto; padding-right: 4px; min-height: 260px; }
.skin-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px; }
.skin-card { background: #0e182acc; border: 2px solid #ffffff1c; border-radius: 12px; padding: 12px; text-align: left; color: #fff; position: relative; transition: .14s; }
.skin-card:hover { transform: translateY(-3px); border-color: #ffffff55; }
.skin-card.selected { border-color: var(--yellow); background: #3b3219cc; box-shadow: 0 0 0 2px #ffd44744; }
.skin-card.locked { opacity: .72; }
.skin-swatch { height: 42px; border-radius: 8px; margin-bottom: 9px; border: 2px solid #0005; box-shadow: inset 0 -8px 0 #0002, inset 0 6px 0 #ffffff30; }
.skin-name { font-weight: 900; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.skin-meta { font-size: 9px; font-weight: 900; letter-spacing: .1em; color: var(--muted); margin-top: 4px; }
.skin-card.selected .skin-meta { color: var(--yellow); }
.skin-price { position: absolute; top: 16px; right: 16px; background: #07101ecc; border-radius: 6px; padding: 3px 7px; color: var(--yellow); font-size: 10px; font-weight: 900; }
.how-modal { width: min(760px, 100%); }
.how-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 10px; padding: 20px 26px 10px; overflow-y: auto; }
.how-grid div { display: flex; flex-direction: column; gap: 3px; background: #ffffff0a; border-radius: 9px; padding: 10px 13px; }
.how-grid b { color: var(--yellow); font-size: 12px; letter-spacing: .08em; } .how-grid span { color: var(--muted); font-size: 11px; font-weight: 800; }
.how-note { padding: 0 26px 22px; color: #a9bcd8; font-size: 12px; font-weight: 800; line-height: 1.6; }
.pause-modal, .end-modal { width: min(560px, 100%); text-align: center; padding: 34px; }
