.end-results span { font-size: 9px; font-weight: 900; letter-spacing: .12em; color: var(--muted); }
.toast { position: absolute; left: 50%; bottom: 90px; transform: translate(-50%, 20px); background: #0b1525f0; border: 2px solid var(--mint); color: #fff; border-radius: 10px; padding: 11px 18px; font-weight: 900; font-size: 12px; z-index: 60; opacity: 0; pointer-events: none; transition: .2s; box-shadow: 0 10px 30px #0008; }
