/* ---------- touch ---------- */
#touchControls { position: absolute; inset: 0; z-index: 25; pointer-events: none; }
.touch-move { position: absolute; left: max(22px, env(safe-area-inset-left)); bottom: max(40px, env(safe-area-inset-bottom)); width: 120px; height: 120px; border-radius: 50%; background: #ffffff10; border: 2px solid #ffffff38; pointer-events: auto; touch-action: none; }
.stick { position: absolute; left: 50%; top: 50%; width: 52px; height: 52px; margin: -26px 0 0 -26px; border-radius: 50%; background: #ffffff40; border: 2px solid #ffffff70; }
.touch-look { position: absolute; right: 130px; top: 80px; bottom: 130px; width: 45%; pointer-events: auto; touch-action: none; }
.touch-buttons { position: absolute; right: max(18px, env(safe-area-inset-right)); bottom: max(28px, env(safe-area-inset-bottom)); display: grid; grid-template-columns: repeat(2, 66px); gap: 10px; pointer-events: auto; }
