import * as THREE from 'three'

const matCache = new Map()
export function mat(color, opts = {}) {
  const key = `${color}-${opts.emissive || 0}-${opts.transparent || false}-${opts.opacity || 1}-${opts.flat || false}`
  if (matCache.has(key)) return matCache.get(key)
  const m = new THREE.MeshLambertMaterial({
    color,
    emissive: opts.emissive || 0x000000,
    emissiveIntensity: opts.emissive ? (opts.emissiveIntensity || 0.8) : 0,
    transparent: !!opts.transparent,
    opacity: opts.opacity ?? 1,
    flatShading: !!opts.flat,
  })
  matCache.set(key, m)
  return m
}

const geoCache = new Map()
function box(w, h, d) {
  const key = `${w}|${h}|${d}`
  if (!geoCache.has(key)) geoCache.set(key, new THREE.BoxGeometry(w, h, d))
  return geoCache.get(key)
}
export function boxMesh(w, h, d, color, opts) {
  const m = new THREE.Mesh(box(w, h, d), mat(color, opts))
  m.castShadow = true
  m.receiveShadow = true
  return m
}

function makeNameTexture(name, hp, color, showHp) {
  const c = document.createElement('canvas')
  c.width = 256; c.height = 72
  const ctx = c.getContext('2d')
  ctx.clearRect(0, 0, 256, 72)
  ctx.font = '900 26px Nunito, Trebuchet MS, sans-serif'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.lineWidth = 7
  ctx.strokeStyle = 'rgba(4,9,18,0.92)'
  ctx.strokeText(name, 128, 24)
  ctx.fillStyle = color
  ctx.fillText(name, 128, 24)
  if (showHp) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)'
    ctx.fillRect(58, 46, 140, 12)
    ctx.fillStyle = hp > 55 ? '#5ce1b9' : hp > 25 ? '#ffd447' : '#ff5364'
    ctx.fillRect(60, 48, Math.max(0, 136 * Math.max(0, hp) / 100), 8)
  }
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function createNameTag(name, color, showHp = true) {
  const tex = makeNameTexture(name, 100, color, showHp)
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false, depthWrite: false }))
  sprite.scale.set(2.3, 0.65, 1)
  sprite.position.set(0, 2.45, 0)
  sprite.renderOrder = 20
  sprite.userData.update = (hp) => {
    const old = sprite.material.map
    sprite.material.map = makeNameTexture(name, hp, color, showHp)
    sprite.material.needsUpdate = true
    old?.dispose()
  }
  return sprite
}

function addHat(head, skin) {
  const hc = skin.hatColor
  const g = new THREE.Group()
  switch (skin.hat) {
    case 'cap': {
      const crown = boxMesh(0.62, 0.16, 0.6, hc); crown.position.y = 0.32; g.add(crown)
      const brim = boxMesh(0.6, 0.06, 0.24, hc); brim.position.set(0, 0.28, 0.38); g.add(brim)
      break
    }
    case 'headband': {
      const band = boxMesh(0.63, 0.1, 0.63, hc); band.position.y = 0.14; g.add(band)
      const tail = boxMesh(0.08, 0.28, 0.1, hc); tail.position.set(-0.32, 0.02, -0.3); g.add(tail)
      break
    }
    case 'helmet': {
      const top = boxMesh(0.66, 0.2, 0.66, hc); top.position.y = 0.32; g.add(top)
      const side1 = boxMesh(0.08, 0.26, 0.5, hc); side1.position.set(-0.32, 0.15, 0); g.add(side1)
      const side2 = side1.clone(); side2.position.x = 0.32; g.add(side2)
      break
    }
    case 'visor': {
      const band = boxMesh(0.66, 0.12, 0.66, 0x1d2740); band.position.y = 0.26; g.add(band)
      const glass = boxMesh(0.64, 0.16, 0.08, hc, { emissive: hc, emissiveIntensity: 0.45 }); glass.position.set(0, 0.23, 0.31); g.add(glass)
      break
    }
    case 'beanie': {
      const beanie = boxMesh(0.64, 0.22, 0.64, hc); beanie.position.y = 0.34; g.add(beanie)
      const pom = boxMesh(0.16, 0.16, 0.16, 0xffffff); pom.position.y = 0.49; g.add(pom)
      break
    }
    case 'crown': {
      const base = boxMesh(0.56, 0.13, 0.56, hc); base.position.y = 0.33; g.add(base)
      for (let i = -1; i <= 1; i++) {
        const spike = boxMesh(0.12, 0.18, 0.12, hc); spike.position.set(i * 0.19, 0.48, 0); g.add(spike)
      }
      break
    }
    case 'horns': {
      const l = boxMesh(0.12, 0.34, 0.12, hc); l.position.set(-0.26, 0.42, 0); l.rotation.z = 0.4; g.add(l)
      const r = boxMesh(0.12, 0.34, 0.12, hc); r.position.set(0.26, 0.42, 0); r.rotation.z = -0.4; g.add(r)
      break
    }
    case 'cat': {
      const l = boxMesh(0.17, 0.24, 0.12, hc); l.position.set(-0.2, 0.42, 0); l.rotation.z = 0.2; g.add(l)
      const r = boxMesh(0.17, 0.24, 0.12, hc); r.position.set(0.2, 0.42, 0); r.rotation.z = -0.2; g.add(r)
      break
    }
    default: break
  }
  head.add(g)
  return g
}

/**
 * Creates a blocky Roblox-style avatar.
 * Returns { group, hitMeshes, animate, setHealth, setSkin, weaponAnchor, meleeAnchor, grenadeAnchor, head, body }
 */
export function createBlockAvatar(skin, options = {}) {
  const group = new THREE.Group()
  const hitMeshes = []
  const nameColor = options.nameColor || '#ffffff'
  const scale = options.scale || 1

  const body = new THREE.Group()
  body.scale.setScalar(scale)
  group.add(body)

  const torso = boxMesh(0.66, 0.68, 0.36, skin.torso)
  torso.position.y = 1.08
  body.add(torso)
  torso.userData = { hitZone: 'body', owner: options.owner }
  hitMeshes.push(torso)

  const head = new THREE.Group()
  head.position.y = 1.72
  body.add(head)
  const headMesh = boxMesh(0.58, 0.56, 0.56, skin.head)
  head.add(headMesh)
  headMesh.userData = { hitZone: 'head', owner: options.owner }
  hitMeshes.push(headMesh)

  // blocky face on +Z side
  const eyeWhite = mat(0xffffff)
  const eyeDark = mat(0x1a1a22)
  for (const x of [-0.14, 0.14]) {
    const eye = new THREE.Mesh(box(0.13, 0.15, 0.02), eyeWhite)
    eye.position.set(x, 0.04, 0.29); head.add(eye)
    const pupil = new THREE.Mesh(box(0.06, 0.08, 0.025), eyeDark)
    pupil.position.set(x, 0.03, 0.31); head.add(pupil)
  }
  const mouth = new THREE.Mesh(box(0.2, 0.035, 0.02), eyeDark)
  mouth.position.set(0, -0.16, 0.29); head.add(mouth)
  addHat(head, skin)

  const arms = []
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group()
    pivot.position.set(side * 0.46, 1.36, 0)
    body.add(pivot)
    const arm = boxMesh(0.24, 0.62, 0.26, side < 0 ? skin.arms : skin.torso)
    arm.position.y = -0.31
    pivot.add(arm)
    arm.userData = { hitZone: 'body', owner: options.owner }
    hitMeshes.push(arm)
    const hand = boxMesh(0.25, 0.14, 0.26, skin.head)
    hand.position.y = -0.66
    pivot.add(hand)
    arms.push(pivot)
  }

  const legs = []
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group()
    pivot.position.set(side * 0.17, 0.74, 0)
    body.add(pivot)
    const leg = boxMesh(0.27, 0.66, 0.28, skin.legs)
    leg.position.y = -0.33
    pivot.add(leg)
    leg.userData = { hitZone: 'body', owner: options.owner }
    hitMeshes.push(leg)
    const shoe = boxMesh(0.3, 0.12, 0.36, 0x2a2f3a)
    shoe.position.set(0, -0.68, 0.04)
    pivot.add(shoe)
    legs.push(pivot)
  }

  const weaponAnchor = new THREE.Group()
  weaponAnchor.position.set(0.3, 1.16, 0.42)
  body.add(weaponAnchor)
  const meleeAnchor = new THREE.Group()
  meleeAnchor.position.set(-0.38, 1.02, 0.38)
  body.add(meleeAnchor)
  const grenadeAnchor = new THREE.Group()
  grenadeAnchor.position.set(0.42, 0.92, 0.2)
  body.add(grenadeAnchor)

  let tag = null
  if (options.name) {
    tag = createNameTag(options.name, nameColor, options.showHp !== false)
    group.add(tag)
  }

  let phase = Math.random() * 6
  const api = {
    group, body, head, hitMeshes, weaponAnchor, meleeAnchor, grenadeAnchor, tag,
    setHealth(hp) { tag?.userData.update(Math.max(0, Math.round(hp))) },
    animate(dt, speed = 0, airborne = false, aiming = false) {
      phase += dt * (4 + speed * 1.5)
      const walk = Math.min(1, speed / 5)
      const swing = Math.sin(phase) * 0.72 * walk
      if (airborne) {
        arms[0].rotation.x = -1.5; arms[1].rotation.x = -1.5
        legs[0].rotation.x = 0.4; legs[1].rotation.x = -0.4
      } else {
        arms[0].rotation.x = aiming ? -1.25 : swing
        arms[1].rotation.x = aiming ? -1.05 : -swing
        arms[0].rotation.z = aiming ? -0.2 : 0.04
        arms[1].rotation.z = aiming ? 0.22 : -0.04
        legs[0].rotation.x = -swing
        legs[1].rotation.x = swing
      }
      body.position.y = airborne ? 0 : Math.abs(Math.sin(phase)) * 0.045 * walk
      head.rotation.z = Math.sin(phase * 0.5) * 0.03 * walk
    },
    setDead(dead) {
      body.rotation.x = dead ? -1.35 : 0
      body.position.y = dead ? -0.55 : 0
      if (tag) tag.visible = !dead
    },
    setSkin(newSkin) {
      torso.material = mat(newSkin.torso)
      headMesh.material = mat(newSkin.head)
      arms[0].children[0].material = mat(newSkin.arms)
      arms[1].children[0].material = mat(newSkin.torso)
      legs[0].children[0].material = mat(newSkin.legs)
      legs[1].children[0].material = mat(newSkin.legs)
      const oldHat = head.children.find(c => c.userData.isHat)
      if (oldHat) head.remove(oldHat)
      const hat = addHat(head, newSkin)
      hat.userData.isHat = true
    },
  }
  const firstHat = head.children[head.children.length - 1]
  if (firstHat) firstHat.userData.isHat = true
  return api
}

/** Build a chunky block gun. Forward direction is local +Z. */
export function createWeaponModel(weapon, skin) {
  const g = new THREE.Group()
  const bodyMat = mat(skin.body)
  const accentMat = mat(skin.accent)
  const glowMat = mat(skin.glow, { emissive: skin.glow, emissiveIntensity: 0.55 })
  let length = 1.1

  const receiver = boxMesh(0.2, 0.22, 0.62, skin.body); g.add(receiver)
  const top = boxMesh(0.16, 0.08, 0.5, skin.accent); top.position.y = 0.15; g.add(top)
  const grip = boxMesh(0.13, 0.3, 0.16, skin.accent); grip.position.set(0, -0.24, -0.1); grip.rotation.x = 0.25; g.add(grip)
  const mag = boxMesh(0.14, 0.34, 0.2, skin.accent); mag.position.set(0, -0.26, 0.16); mag.rotation.x = -0.14; g.add(mag)

  if (weapon.id === 'sniper') {
    const barrel = boxMesh(0.1, 0.1, 0.95, skin.accent); barrel.position.set(0, 0.06, 0.72); g.add(barrel)
    const scope = boxMesh(0.13, 0.13, 0.42, skin.body); scope.position.set(0, 0.28, 0.12); g.add(scope)
    const lens = boxMesh(0.11, 0.11, 0.04, skin.glow, { emissive: skin.glow, emissiveIntensity: 0.7 }); lens.position.set(0, 0.28, 0.35); g.add(lens)
    length = 1.2
  } else if (weapon.id === 'shotgun') {
    const barrel = boxMesh(0.16, 0.16, 0.72, skin.accent); barrel.position.set(0, 0.04, 0.62); g.add(barrel)
    const pump = boxMesh(0.19, 0.13, 0.3, skin.body); pump.position.set(0, -0.07, 0.5); g.add(pump)
    length = 0.98
  } else if (weapon.id === 'smg') {
    const barrel = boxMesh(0.1, 0.1, 0.4, skin.accent); barrel.position.set(0, 0.03, 0.5); g.add(barrel)
    const sight = boxMesh(0.06, 0.1, 0.06, skin.glow, { emissive: skin.glow, emissiveIntensity: 0.8 }); sight.position.set(0, 0.23, 0.28); g.add(sight)
    length = 0.72
  } else {
    const barrel = boxMesh(0.1, 0.1, 0.62, skin.accent); barrel.position.set(0, 0.03, 0.6); g.add(barrel)
    const sight = boxMesh(0.05, 0.09, 0.05, skin.glow, { emissive: skin.glow, emissiveIntensity: 0.8 }); sight.position.set(0, 0.23, 0.32); g.add(sight)
    length = 0.92
  }

  const muzzle = boxMesh(0.12, 0.12, 0.1, skin.body); muzzle.position.set(0, 0.03, length); g.add(muzzle)
  const flash = boxMesh(0.26, 0.26, 0.34, 0xfff2a0, { emissive: 0xffc93c, emissiveIntensity: 1 })
  flash.position.set(0, 0.03, length + 0.2); flash.visible = false; g.add(flash)

  g.userData = {
    muzzle: new THREE.Vector3(0, 0.03, length + 0.08),
    flash,
    bodyMat, accentMat, glowMat,
    applySkin(s) {
      receiver.material = mat(s.body)
      top.material = mat(s.accent)
      grip.material = mat(s.accent)
      mag.material = mat(s.accent)
      muzzle.material = mat(s.body)
      glowMat.color.set(s.glow); glowMat.emissive.set(s.glow)
      g.traverse(o => {
        if (o.isMesh && o.material === mat(skin.body)) o.material = mat(s.body)
      })
      g.userData.skin = s
    },
    skin,
  }
  g.scale.setScalar(1.05)
  return g
}

export function createMeleeModel(skin) {
  const g = new THREE.Group()
  const handle = boxMesh(0.09, 0.34, 0.09, skin.accent); handle.position.y = -0.1; g.add(handle)
  const blade = boxMesh(0.12, 0.85, 0.11, skin.body); blade.position.y = 0.48; g.add(blade)
  const tip = boxMesh(0.13, 0.14, 0.12, skin.glow, { emissive: skin.glow, emissiveIntensity: 0.4 }); tip.position.y = 0.95; g.add(tip)
  g.rotation.z = -0.5
  return g
}

export function createGrenadeModel(skin) {
  const g = new THREE.Group()
  const core = boxMesh(0.22, 0.22, 0.22, skin.body); g.add(core)
  const band = boxMesh(0.24, 0.06, 0.24, skin.accent); band.position.y = 0.02; g.add(band)
  const pin = boxMesh(0.05, 0.05, 0.13, skin.glow, { emissive: skin.glow, emissiveIntensity: 0.5 }); pin.position.set(0.06, 0.14, 0); g.add(pin)
  return g
}

export function makeCubeTexture(color1, color2, size = 256) {
  const c = document.createElement('canvas'); c.width = c.height = size
  const ctx = c.getContext('2d')
  ctx.fillStyle = `#${new THREE.Color(color1).getHexString()}`
  ctx.fillRect(0, 0, size, size)
  ctx.fillStyle = `#${new THREE.Color(color2).getHexString()}`
  for (let y = 0; y < 8; y++) for (let x = 0; x < 8; x++) {
    if ((x + y) % 2 === 0) ctx.fillRect(x * size / 8, y * size / 8, size / 8, size / 8)
  }
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.magFilter = THREE.NearestFilter
  return tex
}

import * as THREE from 'three'
import { boxMesh, mat, createBlockAvatar, createWeaponModel, makeCubeTexture } from './avatar.js'
import { ARENA_HALF, AVATAR_SKINS, GUN_SKINS, WEAPONS } from './data.js'

function textPlane(text, color = '#ffffff', width = 6, height = 1.2, sub = '') {
  const c = document.createElement('canvas')
  c.width = 1024; c.height = 200
  const ctx = c.getContext('2d')
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle'
  ctx.font = '900 108px Nunito, Trebuchet MS, sans-serif'
  ctx.lineWidth = 16; ctx.strokeStyle = '#070d17'
  ctx.strokeText(text, 512, sub ? 78 : 100)
  ctx.fillStyle = color
  ctx.fillText(text, 512, sub ? 78 : 100)
  if (sub) {
    ctx.font = '900 40px Nunito, Trebuchet MS, sans-serif'
    ctx.lineWidth = 9
    ctx.strokeText(sub, 512, 158)
    ctx.fillStyle = '#9fb0cb'
    ctx.fillText(sub, 512, 158)
  }
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(width, height), new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthWrite: false, side: THREE.DoubleSide }))
  return plane
}

function skyDome(scene, top = 0x4a9fe8, bottom = 0xc8e9ff) {
  const geo = new THREE.SphereGeometry(300, 24, 16)
  const material = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false,
    uniforms: { topColor: { value: new THREE.Color(top) }, bottomColor: { value: new THREE.Color(bottom) } },
    vertexShader: 'varying vec3 vWorld; void main(){ vWorld = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
    fragmentShader: 'uniform vec3 topColor; uniform vec3 bottomColor; varying vec3 vWorld; void main(){ float h = normalize(vWorld).y * 0.5 + 0.5; gl_FragColor = vec4(mix(bottomColor, topColor, smoothstep(0.28,0.78,h)),1.0); }',
  })
  const dome = new THREE.Mesh(geo, material)
  scene.add(dome)
  return dome
}

function addCloud(group, x, y, z, s = 1) {
  const cloud = new THREE.Group()
  const c = 0xf4fbff
  const parts = [[0, 0, 0, 3.4, 1.2, 1.8], [-2, -0.2, 0, 2.2, 0.9, 1.5], [2, -0.1, 0, 2.4, 1, 1.5], [0.6, 0.7, 0, 2, 0.9, 1.4]]
  for (const [px, py, pz, w, h, d] of parts) {
    const b = boxMesh(w, h, d, c); b.position.set(px, py, pz); b.castShadow = false; cloud.add(b)
  }
  cloud.position.set(x, y, z); cloud.scale.setScalar(s)
  group.add(cloud)
  return cloud
}

/** Build the combat arena. */
export function createArena() {
  const scene = new THREE.Scene()
  scene.fog = new THREE.Fog(0xa9d8f5, 55, 155)
  skyDome(scene)
  scene.add(new THREE.HemisphereLight(0xdff1ff, 0x4a6a4a, 1.5))
  const sun = new THREE.DirectionalLight(0xfff4d6, 2.0)
  sun.position.set(28, 46, 18)
  sun.castShadow = true
  sun.shadow.mapSize.set(2048, 2048)
  sun.shadow.camera.left = -55; sun.shadow.camera.right = 55
  sun.shadow.camera.top = 55; sun.shadow.camera.bottom = -55
  sun.shadow.camera.near = 1; sun.shadow.camera.far = 130
  sun.shadow.bias = -0.0006
  scene.add(sun)
  scene.add(new THREE.AmbientLight(0xffffff, 0.35))

  const colliders = []
  const solidMeshes = []
  const world = new THREE.Group()
  scene.add(world)

  function addBox(x, y, z, w, h, d, color, opts = {}) {
    const m = boxMesh(w, h, d, color, opts.material || {})
    m.position.set(x, y, z)
    if (opts.rotY) m.rotation.y = opts.rotY
    if (opts.map) m.material = mat(0xffffff, {}) ; // map handled separately below
    world.add(m)
    if (opts.solid) {
      const hw = w / 2, hd = d / 2
      let minX = x - hw, maxX = x + hw, minZ = z - hd, maxZ = z + hd
      if (opts.rotY) {
        const c = Math.abs(Math.cos(opts.rotY)), s = Math.abs(Math.sin(opts.rotY))
        const ew = hw * c + hd * s, ed = hw * s + hd * c
        minX = x - ew; maxX = x + ew; minZ = z - ed; maxZ = z + ed
      }
      colliders.push(new THREE.Box3(new THREE.Vector3(minX, y - h / 2, minZ), new THREE.Vector3(maxX, y + h / 2, maxZ)))
      solidMeshes.push(m)
    }
    return m
  }

  // Ground with big block checker.
  const groundTex = makeCubeTexture(0x6fc477, 0x62b56b, 256)
  groundTex.wrapS = groundTex.wrapT = THREE.RepeatWrapping
  groundTex.repeat.set(9, 9)
  const ground = new THREE.Mesh(new THREE.BoxGeometry(84, 1, 84), new THREE.MeshLambertMaterial({ map: groundTex }))
  ground.position.y = -0.5
  ground.receiveShadow = true
  world.add(ground)
  solidMeshes.push(ground)

  // Concrete paths and plaza.
  addBox(0, 0.03, 0, 16, 0.08, 16, 0x9aa9b5)
  addBox(0, 0.02, 24, 9, 0.06, 30, 0x8e9da9)
  addBox(0, 0.02, -24, 9, 0.06, 30, 0x8e9da9)
  addBox(24, 0.02, 0, 30, 0.06, 9, 0x8e9da9)
  addBox(-24, 0.02, 0, 30, 0.06, 9, 0x8e9da9)

  // Perimeter walls with colored bands.
  const wallColors = [0xff8a3d, 0x4aa8ff, 0x5ce1b9, 0xffd447]
  for (let i = 0; i < 4; i++) {
    const a = i * Math.PI / 2
    const x = Math.sin(a) * (ARENA_HALF + 1)
    const z = Math.cos(a) * (ARENA_HALF + 1)
    const w = i % 2 === 0 ? (ARENA_HALF * 2 + 6) : 2
    const d = i % 2 === 0 ? 2 : (ARENA_HALF * 2 + 6)
    addBox(x, 2.5, z, w, 5, d, 0x3b4d66, { solid: true })
    addBox(x * 0.97, 4.7, z * 0.97, w * 0.99, 0.5, d * 0.99, wallColors[i])
  }

  // Central platform with stair approaches.
  addBox(0, 0.75, 0, 11, 1.5, 11, 0x6f7f92, { solid: true })
  addBox(0, 1.55, 0, 11.4, 0.14, 11.4, 0x8fa1b3)
  for (const dir of [1, -1]) {
    for (let i = 0; i < 3; i++) {
      addBox(0, 0.25 + i * 0.5, dir * (7 + i * 1.1), 7, 0.5 + i * 0.5, 1.1, 0x7b8b9c, { solid: true })
      addBox(dir * (7 + i * 1.1), 0.25 + i * 0.5, 0, 1.1, 0.5 + i * 0.5, 7, 0x7b8b9c, { solid: true })
    }
  }
  // Center beacon
  addBox(0, 2.1, 0, 1.2, 1.2, 1.2, 0xffd447, { material: { emissive: 0xffb020, emissiveIntensity: 0.6 } })

  // Raised side towers.
  const towers = [[-24, -18], [24, 18], [24, -18], [-24, 18]]
  towers.forEach(([tx, tz], idx) => {
    addBox(tx, 3, tz, 9, 6, 9, 0x697a8d, { solid: true })
    addBox(tx, 6.1, tz, 9.6, 0.3, 9.6, idx % 2 ? 0x4aa8ff : 0xff8a3d)
    // stair blocks toward center
    const sx = Math.sign(-tx), sz = Math.sign(-tz)
    for (let i = 0; i < 4; i++) {
      addBox(tx + sx * (5.5 + i * 1.05), 0.75 + i * 0.75, tz, 1.1, 1.5 + i * 1.5, 3.4, 0x7b8b9c, { solid: true })
    }
    addBox(tx + sx * 2.6, 6.9, tz, 0.3, 1.4, 8.6, 0xdfe8f2)
    addBox(tx, 6.9, tz + sz * 2.6, 8.6, 1.4, 0.3, 0xdfe8f2)
  })

  // Shipping containers.
  const containers = [
    [-12, 12, 0xff6b57, 0], [12, -12, 0x4aa8ff, 0], [-30, 4, 0xffc93c, Math.PI / 2],
    [30, -4, 0x5ce1b9, Math.PI / 2], [4, 30, 0xff77b0, 0], [-4, -30, 0x9b7cff, 0],
  ]
  containers.forEach(([x, z, c, r]) => {
    addBox(x, 1.6, z, 8, 3.2, 3, c, { solid: true, rotY: r })
    addBox(x, 1.6, z + (r ? 0 : 1.55), 7.6, 0.12, 0.08, 0xffffff)
  })

  // Crates and cover walls.
  const crates = [
    [-8, -10], [8, 10], [-16, 8], [16, -8], [-20, 24], [20, -24], [-30, -22],
    [30, 22], [12, 22], [-12, -22], [0, 16], [0, -16], [-33, 14], [33, -14],
    [18, 4], [-18, -4], [6, -27], [-6, 27],
  ]
  crates.forEach(([x, z], i) => {
    const s = i % 3 === 0 ? 2.6 : 2.1
    addBox(x, s / 2, z, s, s, s, i % 2 ? 0xc79254 : 0xb57e42, { solid: true })
    addBox(x, s - 0.06, z, s + 0.06, 0.1, s + 0.06, 0x8c5f30)
    if (i % 4 === 0) addBox(x + 0.3, s + 0.9, z - 0.2, 1.6, 1.8, 1.6, 0x9d6d39, { solid: true })
  })
  const covers = [[-20, 0, 1], [20, 0, 1], [0, -20, 0], [0, 20, 0], [-10, 28, 0], [10, -28, 0]]
  covers.forEach(([x, z, rot]) => addBox(x, 1.1, z, rot ? 1.4 : 7, 2.2, rot ? 7 : 1.4, 0x8797a8, { solid: true }))

  // Trees around edges.
  const treeSpots = []
  for (let i = -3; i <= 3; i++) {
    treeSpots.push([i * 11, -35], [i * 11, 35], [-35, i * 11], [35, i * 11])
  }
  treeSpots.forEach(([x, z], i) => {
    if (Math.abs(x) < 6 && Math.abs(z) > 30) return
    addBox(x, 1.5, z, 0.8, 3, 0.8, 0x7b5a3a, { solid: true })
    const leaf = [0x3ea85c, 0x4fbe6b, 0x2f9a52][i % 3]
    addBox(x, 3.9, z, 3.4, 2.4, 3.4, leaf)
    addBox(x, 5.5, z, 2.3, 1.6, 2.3, leaf)
  })

  // Spawn pads.
  const spawns = [
    new THREE.Vector3(-30, 0, -30), new THREE.Vector3(30, 0, 30),
    new THREE.Vector3(30, 0, -30), new THREE.Vector3(-30, 0, 30),
    new THREE.Vector3(0, 0, 32), new THREE.Vector3(0, 1.6, 0),
  ]
  spawns.forEach((p, i) => {
    const c = [0xff6b57, 0x4aa8ff, 0xffd447, 0x5ce1b9, 0xff77b0, 0xffffff][i]
    addBox(p.x, 0.05, p.z, 4, 0.1, 4, c, { material: { emissive: c, emissiveIntensity: 0.45 } })
    const ring = new THREE.Mesh(new THREE.TorusGeometry(1.9, 0.1, 6, 4), mat(c, { emissive: c, emissiveIntensity: 0.6 }))
    ring.rotation.x = Math.PI / 2; ring.rotation.z = Math.PI / 4
    ring.position.set(p.x, 0.16, p.z)
    world.add(ring)
  })

  // Health pickups.
  const pickups = []
  const pickupSpots = [[-16, 16], [16, -16], [-27, -10], [27, 10], [0, -30]]
  pickupSpots.forEach(([x, z]) => {
    const g = new THREE.Group()
    const core = boxMesh(0.8, 0.8, 0.8, 0x5ce1b9, { emissive: 0x2fae86, emissiveIntensity: 0.7 })
    g.add(core)
    const cross1 = boxMesh(0.55, 0.18, 0.85, 0xffffff); g.add(cross1)
    const cross2 = boxMesh(0.18, 0.55, 0.85, 0xffffff); g.add(cross2)
    const glow = new THREE.PointLight(0x5ce1b9, 1.2, 6)
    g.add(glow)
    g.position.set(x, 1.2, z)
    world.add(g)
    pickups.push({ pos: new THREE.Vector3(x, 1.2, z), mesh: g, active: true, timer: 0 })
  })

  // Clouds and sky sign.
  const clouds = []
  for (let i = 0; i < 10; i++) {
    clouds.push(addCloud(world, (Math.random() - 0.5) * 160, 32 + Math.random() * 16, (Math.random() - 0.5) * 160, 1 + Math.random()))
  }
  const sign = textPlane('BLOCKSTRIKE', '#ffd447', 22, 4.4, 'FREE-FOR-ALL ARENA')
  sign.position.set(0, 15, -36)
  world.add(sign)

  const sunBall = new THREE.Mesh(new THREE.SphereGeometry(6, 12, 8), mat(0xfff3c4, { emissive: 0xffe9a0, emissiveIntensity: 0.9 }))
  sunBall.position.set(75, 70, -90)
  scene.add(sunBall)

  const waypoints = [
    ...spawns.map(s => s.clone()),
    ...crates.map(([x, z]) => new THREE.Vector3(x, 0, z)),
    ...covers.map(([x, z]) => new THREE.Vector3(x, 0, z)),
    new THREE.Vector3(0, 1.6, 0), new THREE.Vector3(0, 0, 10), new THREE.Vector3(0, 0, -10),
    new THREE.Vector3(-10, 0, 0), new THREE.Vector3(10, 0, 0),
  ]

  return {
    scene, world, colliders, solidMeshes, spawns, waypoints, pickups, clouds, sun,
    update(dt, t) {
      for (const p of pickups) {
        if (p.active) {
          p.mesh.rotation.y += dt * 1.6
          p.mesh.position.y = p.pos.y + Math.sin(t * 2.4 + p.pos.x) * 0.16
        } else {
          p.timer -= dt
          if (p.timer <= 0) {
            p.active = true
            p.mesh.visible = true
          }
        }
      }
      clouds.forEach((c, i) => {
        c.position.x += dt * (0.4 + i * 0.05)
        if (c.position.x > 95) c.position.x = -95
      })
      sign.lookAt(0, 8, 40)
    },
    collide(pos, radius, height) {
      for (const b of colliders) {
        if (pos.x + radius > b.min.x && pos.x - radius < b.max.x &&
            pos.z + radius > b.min.z && pos.z - radius < b.max.z &&
            pos.y + height > b.min.y && pos.y < b.max.y) return true
      }
      return false
    },
    clamp(pos) {
      pos.x = THREE.MathUtils.clamp(pos.x, -ARENA_HALF, ARENA_HALF)
      pos.z = THREE.MathUtils.clamp(pos.z, -ARENA_HALF, ARENA_HALF)
    },
    takePickup(pos) {
      for (const p of pickups) {
        if (p.active && pos.distanceTo(p.pos) < 1.5) {
          p.active = false
          p.mesh.visible = false
          p.timer = 12
          return true
        }
      }
      return false
    },
  }
}

/** A live 3D lobby with NPCs and skin display pedestals. */
export function createLobby() {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0x0d182b)
  scene.fog = new THREE.Fog(0x0d182b, 30, 90)
  scene.add(new THREE.HemisphereLight(0xbfe3ff, 0x24354f, 1.6))
  const key = new THREE.DirectionalLight(0xffe6b8, 2.2)
  key.position.set(12, 22, 14); key.castShadow = true
  key.shadow.mapSize.set(1024, 1024)
  key.shadow.camera.left = -25; key.shadow.camera.right = 25
  key.shadow.camera.top = 25; key.shadow.camera.bottom = -25
  scene.add(key)
  const fill = new THREE.PointLight(0x4aa8ff, 60, 35)
  fill.position.set(-10, 8, -6); scene.add(fill)
  const fill2 = new THREE.PointLight(0xffd447, 50, 35)
  fill2.position.set(10, 8, 6); scene.add(fill2)

  const group = new THREE.Group(); scene.add(group)
  const floorTex = makeCubeTexture(0x263a58, 0x1d2e48, 256)
  floorTex.wrapS = floorTex.wrapT = THREE.RepeatWrapping
  floorTex.repeat.set(7, 7)
  const floor = new THREE.Mesh(new THREE.BoxGeometry(36, 1, 36), new THREE.MeshLambertMaterial({ map: floorTex }))
  floor.position.y = -0.5; floor.receiveShadow = true; group.add(floor)

  // border rails and corner pillars
  for (const s of [-1, 1]) {
    const rail1 = boxMesh(36, 0.5, 0.6, 0x3b5175); rail1.position.set(0, 0.4, s * 17.8); group.add(rail1)
    const rail2 = boxMesh(0.6, 0.5, 36, 0x3b5175); rail2.position.set(s * 17.8, 0.4, 0); group.add(rail2)
  }
  for (const [x, z, c] of [[-16, -16, 0xff8a3d], [16, -16, 0x4aa8ff], [-16, 16, 0x5ce1b9], [16, 16, 0xffd447]]) {
    const p = boxMesh(1.2, 6, 1.2, c); p.position.set(x, 3, z); group.add(p)
    const l = boxMesh(1.5, 0.4, 1.5, c, { emissive: c, emissiveIntensity: 0.6 }); l.position.set(x, 6.2, z); group.add(l)
  }

  // central spawn pad
  const pad = new THREE.Mesh(new THREE.CylinderGeometry(3.4, 3.4, 0.2, 8), mat(0x2b4a6b, { emissive: 0x1d7fa8, emissiveIntensity: 0.35 }))
  pad.position.y = 0.1; group.add(pad)
  const ring = new THREE.Mesh(new THREE.TorusGeometry(2.7, 0.14, 6, 8), mat(0x5ce1b9, { emissive: 0x5ce1b9, emissiveIntensity: 0.7 }))
  ring.rotation.x = Math.PI / 2; ring.position.y = 0.25; group.add(ring)

  // NPC avatars wandering the lobby
  const npcs = []
  for (let i = 0; i < 8; i++) {
    const skin = AVATAR_SKINS[(i + 1) % AVATAR_SKINS.length]
    const names = ['BlockyBoi', 'TinyTitan', 'CubeQueen', 'PixelPunch', 'NoobMaster', 'SquareJoe', 'RespawnKing', 'BrickBoss']
    const avatar = createBlockAvatar(skin, { name: names[i], nameColor: i % 2 ? '#5ce1b9' : '#ffd447', showHp: false, scale: 0.92 })
    avatar.group.position.set(Math.cos(i / 8 * Math.PI * 2) * 8, 0, Math.sin(i / 8 * Math.PI * 2) * 8)
    group.add(avatar.group)
    npcs.push({
      avatar,
      angle: i / 8 * Math.PI * 2,
      radius: 7 + (i % 3) * 1.3,
      speed: 0.22 + (i % 4) * 0.06,
      bob: Math.random() * 6,
    })
  }

  // Gun skin display pedestals
  const pedestals = []
  const pedestalDefs = [
    { x: -9, z: -8, skin: GUN_SKINS[3], weapon: WEAPONS[0], label: 'SUNSET POP' },
    { x: 9, z: -8, skin: GUN_SKINS[6], weapon: WEAPONS[3], label: 'GOLDEN BOY' },
    { x: -9, z: 8, skin: GUN_SKINS[5], weapon: WEAPONS[2], label: 'FROSTBITE' },
    { x: 9, z: 8, skin: GUN_SKINS[7], weapon: WEAPONS[1], label: 'GALAXY GYRO' },
  ]
  pedestalDefs.forEach((d, i) => {
    const base = boxMesh(1.8, 1.4, 1.8, 0x324967); base.position.set(d.x, 0.7, d.z); group.add(base)
    const top = boxMesh(2, 0.18, 2, d.skin.body); top.position.set(d.x, 1.48, d.z); group.add(top)
    const glow = new THREE.PointLight(d.skin.glow, 4, 5); glow.position.set(d.x, 2.3, d.z); group.add(glow)
    const model = createWeaponModel(d.weapon, d.skin)
    model.position.set(d.x, 2.1, d.z); model.scale.setScalar(1.7); group.add(model)
    const label = textPlane(d.label, '#ffffff', 3.2, 0.64, d.skin.rarity + ' SKIN')
    label.position.set(d.x, 3.3, d.z); group.add(label)
    pedestals.push({ model, label, baseY: 2.1 })
  })

  // Big lobby banner
  const banner = textPlane('BLOCKSTRIKE', '#ffd447', 14, 2.8, 'LOBBY · 9 PLAYERS ONLINE')
  banner.position.set(0, 8, -15)
  group.add(banner)
  const subBanner = textPlane('CUSTOMIZE · QUEUE · FIGHT', '#5ce1b9', 9, 1.4)
  subBanner.position.set(0, 5.7, -15)
  group.add(subBanner)

  // floating decorative blocks
  const floaters = []
  for (let i = 0; i < 18; i++) {
    const c = [0xffd447, 0x5ce1b9, 0x4aa8ff, 0xff8a3d][i % 4]
    const b = boxMesh(0.35, 0.35, 0.35, c, { emissive: c, emissiveIntensity: 0.25 })
    b.position.set((Math.random() - 0.5) * 30, 2 + Math.random() * 8, (Math.random() - 0.5) * 30)
    group.add(b); floaters.push({ mesh: b, y: b.position.y, phase: Math.random() * 6 })
  }

  const camera = new THREE.PerspectiveCamera(52, 1, 0.1, 200)
  let orbit = 0.55

  return {
    scene, camera, group,
    rotate(dx) { orbit += dx * 0.004 },
    update(dt, t) {
      orbit += dt * 0.055
      const r = 17
      camera.position.set(Math.sin(orbit) * r, 7.5 + Math.sin(t * 0.35) * 0.5, Math.cos(orbit) * r)
      camera.lookAt(0, 2.4, 0)
      npcs.forEach((n, i) => {
        n.angle += dt * n.speed
        n.avatar.group.position.x = Math.cos(n.angle) * n.radius
        n.avatar.group.position.z = Math.sin(n.angle) * n.radius
        n.avatar.group.rotation.y = -n.angle + Math.PI / 2
        n.avatar.animate(dt, 2.1, false, false)
        n.avatar.group.position.y = Math.abs(Math.sin(t * 5 + n.bob)) * 0.06
        if (i % 3 === 0) n.avatar.body.rotation.z = Math.sin(t * 3 + n.bob) * 0.1
      })
      pedestals.forEach((p, i) => {
        p.model.rotation.y = t * 0.5 + i
        p.model.position.y = p.baseY + Math.sin(t * 1.6 + i) * 0.12
      })
      ring.rotation.z += dt * 0.6
      floaters.forEach(f => {
        f.mesh.position.y = f.y + Math.sin(t * 1.2 + f.phase) * 0.4
        f.mesh.rotation.x += dt; f.mesh.rotation.y += dt * 0.7
      })
      banner.lookAt(camera.position)
      subBanner.lookAt(camera.position)
      pedestals.forEach(p => p.label.lookAt(camera.position))
    },
  }
}

import * as THREE from 'three'
import { boxMesh, mat } from './avatar.js'

export class Effects {
  constructor(scene) {
    this.scene = scene
    this.items = []
    this.geo = new THREE.BoxGeometry(1, 1, 1)
  }

  tracer(from, to, color = 0xffd447, width = 0.05, life = 0.09) {
    const dir = new THREE.Vector3().subVectors(to, from)
    const len = dir.length()
    if (len < 0.01) return
    const mesh = new THREE.Mesh(this.geo, new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, depthWrite: false }))
    mesh.position.copy(from).addScaledVector(dir, 0.5)
    mesh.scale.set(width, width, len)
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), dir.clone().normalize())
    this.scene.add(mesh)
    this.items.push({ mesh, life, max: life, kind: 'fade' })
  }

  impact(point, color = 0xffd447, count = 7) {
    for (let i = 0; i < count; i++) {
      const mesh = new THREE.Mesh(this.geo, new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1, depthWrite: false }))
      const s = 0.06 + Math.random() * 0.09
      mesh.scale.setScalar(s)
      mesh.position.copy(point)
      this.scene.add(mesh)
      const v = new THREE.Vector3((Math.random() - 0.5) * 6, Math.random() * 5, (Math.random() - 0.5) * 6)
      this.items.push({ mesh, life: 0.5 + Math.random() * 0.3, max: 0.8, kind: 'particle', v })
    }
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.08, 0.16, 8), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, side: THREE.DoubleSide, depthWrite: false }))
    ring.position.copy(point); ring.lookAt(point.clone().add(new THREE.Vector3(0, 1, 0)))
    this.scene.add(ring)
    this.items.push({ mesh: ring, life: 0.25, max: 0.25, kind: 'fade' })
  }

  blood(point) {
    this.impact(point, 0xff5c6b, 5)
  }

  explosion(point, radius = 4) {
    const ball = new THREE.Mesh(new THREE.SphereGeometry(1, 10, 8), new THREE.MeshBasicMaterial({ color: 0xffb03d, transparent: true, opacity: 0.9, depthWrite: false }))
    ball.position.copy(point); ball.scale.setScalar(0.3)
    this.scene.add(ball)
    this.items.push({ mesh: ball, life: 0.45, max: 0.45, kind: 'explode', radius })
    for (let i = 0; i < 22; i++) {
      const mesh = new THREE.Mesh(this.geo, new THREE.MeshBasicMaterial({ color: i % 2 ? 0xffd447 : 0xff6b3d, transparent: true, opacity: 1, depthWrite: false }))
      mesh.scale.setScalar(0.12 + Math.random() * 0.15)
      mesh.position.copy(point)
      this.scene.add(mesh)
      const v = new THREE.Vector3(Math.random() - 0.5, Math.random() * 0.9, Math.random() - 0.5).normalize().multiplyScalar(9 + Math.random() * 9)
      this.items.push({ mesh, life: 0.6 + Math.random() * 0.4, max: 1, kind: 'particle', v })
    }
  }

  damageNumber(point, amount, head = false) {
    const c = document.createElement('canvas'); c.width = 128; c.height = 64
    const ctx = c.getContext('2d')
    ctx.font = '900 40px Nunito, Trebuchet MS, sans-serif'
    ctx.textAlign = 'center'
    ctx.lineWidth = 8; ctx.strokeStyle = '#000'
    ctx.strokeText(String(amount), 64, 44)
    ctx.fillStyle = head ? '#ffd447' : '#ffffff'
    ctx.fillText(String(amount), 64, 44)
    const tex = new THREE.CanvasTexture(c); tex.colorSpace = THREE.SRGBColorSpace
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false, depthWrite: false }))
    sp.scale.set(1.3, 0.65, 1); sp.position.copy(point); sp.renderOrder = 25
    this.scene.add(sp)
    this.items.push({ mesh: sp, life: 0.75, max: 0.75, kind: 'float', v: new THREE.Vector3((Math.random() - 0.5) * 0.5, 1.6, 0) })
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const it = this.items[i]
      it.life -= dt
      const t = Math.max(0, it.life / it.max)
      if (it.kind === 'particle') {
        it.v.y -= 15 * dt
        it.mesh.position.addScaledVector(it.v, dt)
        if (it.mesh.position.y < 0.05) { it.mesh.position.y = 0.05; it.v.y *= -0.3; it.v.x *= 0.6; it.v.z *= 0.6 }
        it.mesh.material.opacity = t
      } else if (it.kind === 'explode') {
        it.mesh.scale.setScalar(0.3 + (1 - t) * it.radius)
        it.mesh.material.opacity = t * 0.8
      } else if (it.kind === 'float') {
        it.mesh.position.addScaledVector(it.v, dt)
        it.v.y *= 0.94
        it.mesh.material.opacity = t
      } else {
        it.mesh.material.opacity = t * 0.9
      }
      if (it.life <= 0) {
        this.scene.remove(it.mesh)
        if (it.mesh.material?.map) it.mesh.material.map.dispose()
        it.mesh.material?.dispose?.()
        this.items.splice(i, 1)
      }
    }
  }
}

// Tiny synthesized sound library - no external audio files needed.
export class Sfx {
  constructor() {
    this.ctx = null
    this.master = null
    this.enabled = true
  }
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.master = this.ctx.createGain()
    this.master.gain.value = 0.32
    this.master.connect(this.ctx.destination)
  }
  tone(freq, dur, type = 'square', vol = 0.25, slide = 0) {
    if (!this.enabled || !this.ctx) return
    const t = this.ctx.currentTime
    const o = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    o.type = type
    o.frequency.setValueAtTime(freq, t)
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur)
    g.gain.setValueAtTime(vol, t)
    g.gain.exponentialRampToValueAtTime(0.001, t + dur)
    o.connect(g); g.connect(this.master)
    o.start(t); o.stop(t + dur + 0.02)
  }
  noise(dur = 0.1, vol = 0.25, filterFreq = 1200) {
    if (!this.enabled || !this.ctx) return
    const t = this.ctx.currentTime
    const len = Math.floor(this.ctx.sampleRate * dur)
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = buf.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len)
    const src = this.ctx.createBufferSource(); src.buffer = buf
    const filter = this.ctx.createBiquadFilter(); filter.type = 'lowpass'; filter.frequency.value = filterFreq
    const g = this.ctx.createGain(); g.gain.value = vol
    src.connect(filter); filter.connect(g); g.connect(this.master)
    src.start()
  }
  shoot(weapon) {
    if (weapon === 'shotgun') { this.noise(0.22, 0.5, 900); this.tone(90, 0.16, 'sawtooth', 0.3, -50) }
    else if (weapon === 'sniper') { this.noise(0.28, 0.45, 1800); this.tone(140, 0.22, 'square', 0.22, -90) }
    else if (weapon === 'smg') { this.noise(0.06, 0.25, 2400); this.tone(210, 0.05, 'square', 0.12, -60) }
    else { this.noise(0.1, 0.35, 2000); this.tone(160, 0.08, 'square', 0.18, -70) }
  }
  hit() { this.tone(880, 0.06, 'sine', 0.22, 220) }
  headshot() { this.tone(1200, 0.09, 'sine', 0.25, 600); this.tone(1600, 0.12, 'triangle', 0.15, 400) }
  kill() { this.tone(660, 0.1, 'triangle', 0.25); setTimeout(() => this.tone(990, 0.18, 'triangle', 0.22), 85) }
  hurt() { this.tone(140, 0.16, 'sawtooth', 0.25, -60); this.noise(0.08, 0.18, 500) }
  jump() { this.tone(330, 0.1, 'square', 0.12, 200) }
  land() { this.noise(0.07, 0.14, 300) }
  reload() { this.tone(300, 0.05, 'square', 0.14); setTimeout(() => this.tone(420, 0.06, 'square', 0.14), 170) }
  pickup() { this.tone(660, 0.08, 'sine', 0.2); setTimeout(() => this.tone(990, 0.14, 'sine', 0.2), 80) }
  click() { this.tone(520, 0.04, 'square', 0.1) }
  buy() { this.tone(523, 0.09, 'triangle', 0.2); setTimeout(() => this.tone(784, 0.14, 'triangle', 0.2), 90) }
  deny() { this.tone(180, 0.14, 'sawtooth', 0.18, -60) }
  swing() { this.noise(0.12, 0.18, 800) }
  tick() { this.tone(880, 0.06, 'sine', 0.12) }
}

// Cross-tab multiplayer. Uses BroadcastChannel so opening the game in another
// browser tab adds a real human player to your match. The oldest tab is host
// and owns bot health; other tabs send hit events to it.
export class ArenaNet {
  constructor(handlers = {}) {
    this.handlers = handlers
    this.id = Math.random().toString(36).slice(2, 10)
    this.born = Date.now() + Math.random()
    this.peers = new Map()
    this.host = false
    this.channel = typeof BroadcastChannel !== 'undefined' ? new BroadcastChannel('blockstrike-arena-v1') : null
    this.lastState = 0
    if (this.channel) {
      this.channel.onmessage = (e) => this.onMessage(e.data)
      this.send('hello', { id: this.id, born: this.born })
    }
  }

  send(type, data = {}, target = null) {
    if (!this.channel) return
    this.channel.postMessage({ type, from: this.id, to: target, born: this.born, data })
  }

  get peerCount() { return this.peers.size + 1 }

  recomputeHost() {
    let host = true
    for (const p of this.peers.values()) if (p.born < this.born) host = false
    if (host !== this.host) {
      this.host = host
      this.handlers.onHostChange?.(host)
    }
  }

  onMessage(msg) {
    if (!msg || msg.from === this.id) return
    if (msg.to && msg.to !== this.id) return
    const d = msg.data || {}
    if (msg.type === 'hello') {
      this.peers.set(msg.from, { id: msg.from, born: msg.born, last: performance.now(), state: null })
      this.send('welcome', { id: this.id, born: this.born }, msg.from)
      this.recomputeHost()
      return
    }
    if (msg.type === 'welcome' || msg.type === 'state') {
      if (!this.peers.has(msg.from)) this.peers.set(msg.from, { id: msg.from, born: msg.born, last: performance.now(), state: null })
      const p = this.peers.get(msg.from)
      p.last = performance.now()
      if (msg.type === 'state') {
        p.state = d
        this.handlers.onPeerState?.(msg.from, d)
      } else {
        this.handlers.onPeerState?.(msg.from, d.state || null)
      }
      this.recomputeHost()
      return
    }
    switch (msg.type) {
      case 'botHit': this.handlers.onRemoteBotHit?.(d); break
      case 'botHp': this.handlers.onBotHp?.(d); break
      case 'playerDamage': this.handlers.onPlayerDamage?.(d); break
      case 'kill': this.handlers.onRemoteKill?.(d); break
      case 'leave': this.peers.delete(msg.from); this.recomputeHost(); this.handlers.onPeerLeave?.(msg.from); break
      default: break
    }
  }

  broadcastPlayerState(state) {
    const now = performance.now()
    if (now - this.lastState < 55) return
    this.lastState = now
    this.send('state', state)
  }

  update() {
    const now = performance.now()
    for (const [id, p] of this.peers) {
      if (now - p.last > 4000) {
        this.peers.delete(id)
        this.handlers.onPeerLeave?.(id)
        this.recomputeHost()
      }
    }
  }

  leave() {
    this.send('leave', {})
    this.channel?.close()
    this.channel = null
    this.peers.clear()
  }
}

import * as THREE from 'three'
import { createBlockAvatar, createWeaponModel, createMeleeModel, createGrenadeModel, mat } from './avatar.js'
import { ALL_SKINS, WEAPONS, KILL_TARGET, ARENA_HALF } from './data.js'

const $ = (id) => document.getElementById(id)

export class UI {
  constructor(game) {
    this.game = game
    this.el = {
      loading: $('loading'), menu: $('menu'), hud: $('hud'), pause: $('pause'),
      customize: $('customize'), how: $('how'), scoreboard: $('scoreboard'), matchEnd: $('matchEnd'),
      touch: $('touchControls'), toast: $('toast'),
      menuCoins: $('menuCoins'), menuOnline: $('menuOnline'),
      statKills: $('statKills'), statWins: $('statWins'), statBest: $('statBest'),
      loadoutSkinName: $('loadoutSkinName'), loadoutGunName: $('loadoutGunName'),
      loadoutAvatar: $('loadoutAvatar'),
      matchTime: $('matchTime'), matchProgress: $('matchProgress'),
      hudKills: $('hudKills'), leaderboardMini: $('leaderboardMini'),
      killfeed: $('killfeed'), crosshair: $('crosshair'), hitmarker: $('hitmarker'),
      scope: $('scopeOverlay'), damage: $('damageVignette'), lowHealth: $('lowHealth'),
      killBanner: $('killBanner'), killBannerTitle: $('killBannerTitle'), killBannerSub: $('killBannerSub'),
      respawn: $('respawn'), respawnTime: $('respawnTime'), respawnTip: $('respawnTip'),
      healthValue: $('healthValue'), healthBar: $('healthBar'),
      weaponSlots: $('weaponSlots'), ammoWeapon: $('ammoWeapon'), ammoSkin: $('ammoSkin'),
      ammoCurrent: $('ammoCurrent'), ammoReserve: $('ammoReserve'),
      reloadBar: $('reloadBar'), reloadHint: $('reloadHint'),
      scoreboardTime: $('scoreboardTime'), scoreRows: $('scoreRows'),
      custCoins: $('custCoins'), skinGrid: $('skinGrid'), previewLabel: $('previewLabel'), previewSub: $('previewSub'),
      endTitle: $('endTitle'), endSub: $('endSub'), endResults: $('endResults'),
      pickupToast: $('pickupToast'),
    }
    this.activeTab = 'avatar'
    this.lastHit = 0
    this.lastKillBanner = 0
    this.toastTimer = 0
    this.pickupTimer = 0
    this.setupPreview()
    this.bindMenuButtons()
    this.bindTouch()
    this.refreshLoadout()
  }

  bindMenuButtons() {
    $('playBtn').onclick = () => this.game.startMatch()
    $('customizeBtn').onclick = () => this.openCustomize('avatar')
    $('howBtn').onclick = () => { this.el.how.classList.remove('hidden'); this.game.sfx?.click() }
    $('closeHow').onclick = () => this.el.how.classList.add('hidden')
    $('closeCustomize').onclick = () => this.closeCustomize()
    $('resumeBtn').onclick = () => this.game.resume()
    $('pauseCustomizeBtn').onclick = () => this.openCustomize('avatar')
    $('quitBtn').onclick = () => this.game.quitToMenu()
    $('rematchBtn').onclick = () => this.game.startMatch()
    $('endCustomizeBtn').onclick = () => this.openCustomize('avatar')
    $('endMenuBtn').onclick = () => this.game.quitToMenu()
    document.querySelectorAll('.cust-tab').forEach(btn => {
      btn.onclick = () => {
        document.querySelectorAll('.cust-tab').forEach(b => b.classList.toggle('active', b === btn))
        this.openCustomize(btn.dataset.tab, true)
      }
    })
  }

  bindTouch() {
    const move = $('touchMove'), stick = $('touchStick'), look = $('touchLook')
    let moveId = null, lookId = null, lx = 0, ly = 0
    const updateStick = (e) => {
      const r = move.getBoundingClientRect()
      let dx = e.clientX - (r.left + r.width / 2), dy = e.clientY - (r.top + r.height / 2)
      const max = r.width * 0.36
      const d = Math.hypot(dx, dy)
      if (d > max) { dx *= max / d; dy *= max / d }
      stick.style.transform = `translate(${dx}px,${dy}px)`
      lx = dx / max; ly = dy / max
      this.game.touchMove = { x: lx, y: ly }
    }
    move.addEventListener('pointerdown', e => { moveId = e.pointerId; move.setPointerCapture(e.pointerId); updateStick(e) })
    move.addEventListener('pointermove', e => { if (e.pointerId === moveId) updateStick(e) })
    const endMove = e => { if (e.pointerId !== moveId) return; moveId = null; stick.style.transform = ''; this.game.touchMove = { x: 0, y: 0 } }
    move.addEventListener('pointerup', endMove); move.addEventListener('pointercancel', endMove)

    let lastX = 0, lastY = 0
    look.addEventListener('pointerdown', e => { lookId = e.pointerId; look.setPointerCapture(e.pointerId); lastX = e.clientX; lastY = e.clientY })
    look.addEventListener('pointermove', e => {
      if (e.pointerId !== lookId) return
      this.game.onMouseMove(e.clientX - lastX, e.clientY - lastY)
      lastX = e.clientX; lastY = e.clientY
    })
    const endLook = e => { if (e.pointerId === lookId) lookId = null }
    look.addEventListener('pointerup', endLook); look.addEventListener('pointercancel', endLook)

    const hold = (id, down, up) => {
      const b = $(id)
      b.addEventListener('pointerdown', e => { e.preventDefault(); b.classList.add('pressed'); down() })
      b.addEventListener('pointerup', e => { e.preventDefault(); b.classList.remove('pressed'); up?.() })
      b.addEventListener('pointercancel', () => { b.classList.remove('pressed'); up?.() })
    }
    hold('touchFire', () => this.game.touchFire = true, () => this.game.touchFire = false)
    hold('touchAim', () => this.game.touchAim = true, () => this.game.touchAim = false)
    $('touchJump').addEventListener('pointerdown', e => { e.preventDefault(); this.game.jump() })
    $('touchReload').addEventListener('pointerdown', e => { e.preventDefault(); this.game.reload() })
    $('touchSwap').addEventListener('pointerdown', e => { e.preventDefault(); this.game.switchWeapon(this.game.player.weaponIndex + 1) })
  }

  setupPreview() {
    const canvas = $('previewCanvas')
    try {
      this.preview = {
        renderer: new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true, powerPreference: 'low-power' }),
        scene: new THREE.Scene(),
        camera: new THREE.PerspectiveCamera(38, 1, 0.1, 50),
      }
      const r = this.preview.renderer
      r.setPixelRatio(Math.min(devicePixelRatio, 1.5))
      r.shadowMap.enabled = true
      r.shadowMap.type = THREE.PCFSoftShadowMap
      const s = this.preview.scene
      s.add(new THREE.HemisphereLight(0xffffff, 0x34435e, 2.2))
      const l = new THREE.DirectionalLight(0xffffff, 2.2); l.position.set(4, 8, 6); l.castShadow = true; s.add(l)
      const floor = new THREE.Mesh(new THREE.CylinderGeometry(1.9, 2.1, 0.16, 12), mat(0x2f4664))
      floor.position.y = -0.02; floor.receiveShadow = true; s.add(floor)
      const ring = new THREE.Mesh(new THREE.TorusGeometry(1.75, 0.05, 6, 16), mat(0x5ce1b9, { emissive: 0x5ce1b9, emissiveIntensity: 0.6 }))
      ring.rotation.x = Math.PI / 2; ring.position.y = 0.08; s.add(ring)
      this.preview.root = new THREE.Group(); s.add(this.preview.root)
      this.preview.camera.position.set(0, 1.75, 5.4)
      this.preview.camera.lookAt(0, 1.1, 0)
      this.preview.ring = ring
      this.rebuildPreview()
    } catch (err) {
      console.warn('Skin preview unavailable:', err)
      this.preview = null
    }
  }

  rebuildPreview() {
    if (!this.preview) return
    const root = this.preview.root
    while (root.children.length) root.remove(root.children[0])
    const g = this.game
    const avatar = createBlockAvatar(g.getSkin('avatar'), { scale: 1.05 })
    root.add(avatar.group)
    const weapon = createWeaponModel(WEAPONS[g.player.weaponIndex], g.getSkin('gun'))
    weapon.position.set(0.3, 1.16, 0.42); weapon.scale.setScalar(1.15)
    root.add(weapon)
    const melee = createMeleeModel(g.getSkin('melee'))
    melee.position.set(-0.42, 0.8, 0.2); melee.scale.setScalar(0.7)
    root.add(melee)
    const grenade = createGrenadeModel(g.getSkin('grenade'))
    grenade.position.set(0.6, 0.55, 0.3); grenade.scale.setScalar(0.9)
    root.add(grenade)
    this.preview.avatar = avatar
  }

  updatePreview(dt, t) {
    if (!this.preview || this.el.customize.classList.contains('hidden')) return
    const r = this.preview.renderer
    const rect = $('previewCanvas').getBoundingClientRect()
    if (rect.width > 0 && rect.height > 0 && (r.domElement.width !== Math.floor(rect.width * r.getPixelRatio()) || r.domElement.height !== Math.floor(rect.height * r.getPixelRatio()))) {
      r.setSize(rect.width, rect.height, false)
      this.preview.camera.aspect = rect.width / rect.height
      this.preview.camera.updateProjectionMatrix()
    }
    this.preview.root.rotation.y += dt * 0.7
    this.preview.ring.rotation.z += dt
    this.preview.renderer.render(this.preview.scene, this.preview.camera)
  }

  show(name) {
    for (const k of ['loading', 'menu', 'hud', 'pause', 'scoreboard', 'matchEnd', 'how']) {
      this.el[k].classList.toggle('hidden', k !== name)
    }
  }

  refreshLoadout() {
    const g = this.game
    const a = g.getSkin('avatar'), w = g.getSkin('gun')
    this.el.loadoutSkinName.textContent = a.name
    this.el.loadoutGunName.textContent = `${WEAPONS[g.player.weaponIndex].name} · ${w.name}`
    this.el.menuCoins.textContent = g.coins
    this.el.statKills.textContent = g.stats.kills
    this.el.statWins.textContent = g.stats.wins
    this.el.statBest.textContent = g.stats.best
    // CSS loadout avatar colors
    const av = this.el.loadoutAvatar
    av.querySelector('.block-head').style.background = `#${a.head.toString(16).padStart(6, '0')}`
    const torso = av.querySelector('.block-body')
    torso.style.background = `#${a.torso.toString(16).padStart(6, '0')}`
    av.querySelector('.block-arms').style.background = `linear-gradient(90deg, #${a.arms.toString(16).padStart(6,'0')} 0 18px, transparent 18px calc(100% - 18px), #${a.torso.toString(16).padStart(6,'0')} calc(100% - 18px))`
    av.querySelector('.block-legs').style.background = `linear-gradient(90deg, #${a.legs.toString(16).padStart(6,'0')} 0 24px, transparent 24px 32px, #${a.legs.toString(16).padStart(6,'0')} 32px)`
    this.el.custCoins.textContent = g.coins
    this.updateWeaponSlots()
  }

  openCustomize(tab = this.activeTab, keepTab = false) {
    this.activeTab = tab
    document.querySelectorAll('.cust-tab').forEach(b => b.classList.toggle('active', b.dataset.tab === tab))
    this.el.customize.classList.remove('hidden')
    this.renderSkins(tab)
    this.rebuildPreview()
    this.game.sfx?.click()
  }

  closeCustomize() {
    this.el.customize.classList.add('hidden')
    this.game.sfx?.click()
    this.refreshLoadout()
    if (this.game.state === 'menu') this.show('menu')
    else if (this.game.state === 'paused') this.show('pause')
  }

  renderSkins(tab) {
    const g = this.game
    const list = ALL_SKINS[tab]
    const owned = g.owned[tab]
    const selected = g.equipped[tab]
    this.el.skinGrid.innerHTML = ''
    list.forEach(s => {
      const isOwned = owned.includes(s.id)
      const isSelected = selected === s.id
      const card = document.createElement('button')
      card.className = 'skin-card' + (isSelected ? ' selected' : '') + (isOwned ? '' : ' locked')
      const c1 = `#${(s.torso ?? s.body).toString(16).padStart(6, '0')}`
      const c2 = `#${(s.legs ?? s.accent ?? s.body ?? 0x333333).toString(16).padStart(6, '0')}`
      card.innerHTML = `
        <div class="skin-swatch" style="background:linear-gradient(135deg, ${c1} 0 48%, ${c2} 48% 100%)"></div>
        <div class="skin-name">${s.name}</div>
        <div class="skin-meta">${isSelected ? '✓ EQUIPPED' : isOwned ? s.rarity : `◈ ${s.price}`}</div>
        ${!isOwned && !isSelected ? `<div class="skin-price">◈ ${s.price}</div>` : ''}
      `
      card.onclick = () => {
        if (isOwned) { g.equipSkin(tab, s.id); this.renderSkins(tab); this.rebuildPreview(); this.refreshLoadout(); this.game.sfx?.click() }
        else if (g.coins >= s.price) { g.buySkin(tab, s); this.renderSkins(tab); this.rebuildPreview(); this.refreshLoadout() }
        else { this.game.sfx?.deny(); this.toast(`Need ${s.price - g.coins} more coins`) }
      }
      this.el.skinGrid.appendChild(card)
    })
    const sel = list.find(s => s.id === selected) || list[0]
    this.el.previewLabel.textContent = sel.name.toUpperCase()
    this.el.previewSub.textContent = `${sel.rarity} · ${tab === 'avatar' ? 'AVATAR SKIN' : tab === 'gun' ? 'WEAPON FINISH' : tab === 'melee' ? 'MELEE SKIN' : 'GRENADE SKIN'}`
  }

  updateWeaponSlots() {
    const g = this.game, p = g.player
    this.el.weaponSlots.innerHTML = ''
    WEAPONS.forEach((w, i) => {
      const d = document.createElement('div')
      d.className = 'wslot' + (i === p.weaponIndex ? ' active' : '')
      d.innerHTML = `<b>${i + 1}</b><span>${w.short}</span><i><em style="width:${Math.max(0, p.ammo[i] / w.mag * 100)}%"></em></i>`
      this.el.weaponSlots.appendChild(d)
    })
  }

  updateHud(game) {
    const p = game.player
    const secs = Math.max(0, Math.ceil(game.matchTime))
    this.el.matchTime.textContent = `${String(Math.floor(secs / 60)).padStart(2, '0')}:${String(secs % 60).padStart(2, '0')}`
    this.el.matchProgress.style.width = `${Math.max(0, secs / game.matchDuration * 100)}%`
    this.el.hudKills.textContent = p.kills
    this.el.healthValue.textContent = Math.max(0, Math.ceil(p.health))
    this.el.healthBar.style.width = `${Math.max(0, p.health)}%`
    this.el.lowHealth.style.opacity = p.health < 30 && p.alive ? '1' : '0'

    const w = WEAPONS[p.weaponIndex]
    this.el.ammoWeapon.textContent = w.name
    this.el.ammoSkin.textContent = game.getSkin('gun').name.toUpperCase()
    this.el.ammoCurrent.textContent = p.ammo[p.weaponIndex]
    this.el.ammoReserve.textContent = p.reserve[p.weaponIndex]
    const reloading = p.reloadTimer > 0
    this.el.reloadBar.classList.toggle('show', reloading)
    this.el.reloadBar.firstElementChild.style.width = reloading ? `${(1 - p.reloadTimer / w.reload) * 100}%` : '0%'
    this.el.reloadHint.textContent = reloading ? 'RELOADING…' : (p.ammo[p.weaponIndex] === 0 ? 'PRESS R TO RELOAD' : 'R TO RELOAD')
    this.el.reloadHint.style.color = p.ammo[p.weaponIndex] === 0 ? '#ff5364' : ''

    this.el.crosshair.classList.toggle('scoped', p.aiming && w.id === 'sniper')
    this.el.scope.classList.toggle('show', p.aiming && w.id === 'sniper')
    this.el.respawn.classList.toggle('hidden', p.alive)
    if (!p.alive) this.el.respawnTime.textContent = Math.max(1, Math.ceil(p.respawnTimer))
    this.el.damage.style.opacity = Math.max(0, (p.damageFlash || 0)) * 0.85

    // Leaderboard (sorted by kills)
    const rows = game.scoreboardEntries()
    this.el.leaderboardMini.innerHTML = rows.slice(0, 5).map((r, i) =>
      `<div class="lb-row ${r.me ? 'me' : ''}"><span>${i + 1}. ${r.name}</span><span>${r.kills}</span></div>`).join('')
    if (!this.el.scoreboard.classList.contains('hidden')) this.updateScoreboard(game)
    this.updateWeaponSlots()
  }

  updateScoreboard(game) {
    const rows = game.scoreboardEntries()
    this.el.scoreRows.innerHTML = rows.map((r, i) =>
      `<div class="score-row ${r.me ? 'me' : ''}"><span>${i + 1}</span><span>${r.name}</span><span>${r.kills}</span><span>${r.deaths}</span><span>${r.streak}</span></div>`).join('')
    this.el.scoreboardTime.textContent = `${Math.ceil(game.matchTime)}s REMAINING · FIRST TO ${KILL_TARGET}`
  }

  addKill(killer, victim, weapon, head) {
    const d = document.createElement('div')
    d.className = 'kf-item'
    d.innerHTML = `<b>${killer}</b> ${head ? '☠' : '✕'} ${weapon} ${head ? 'HEADSHOT' : ''} <i>${victim}</i>`
    this.el.killfeed.prepend(d)
    setTimeout(() => d.remove(), 5200)
    while (this.el.killfeed.children.length > 5) this.el.killfeed.lastChild.remove()
  }

  showHit(head) {
    const now = performance.now()
    if (now - this.lastHit < 40) return
    this.lastHit = now
    this.el.hitmarker.classList.toggle('head', head)
    this.el.hitmarker.classList.add('show')
    clearTimeout(this._hitTimer)
    this._hitTimer = setTimeout(() => this.el.hitmarker.classList.remove('show'), 120)
  }

  showKillBanner(name, coins) {
    this.el.killBannerTitle.textContent = name === 'HEADSHOT!' ? 'HEADSHOT!' : 'ELIMINATED!'
    this.el.killBannerSub.textContent = `+${coins} ◈  ${name !== 'HEADSHOT!' ? name.toUpperCase() : ''}`
    this.el.killBanner.classList.add('show')
    clearTimeout(this._killTimer)
    this._killTimer = setTimeout(() => this.el.killBanner.classList.remove('show'), 1400)
  }

  showPickup(text) {
    this.el.pickupToast.textContent = text
    this.el.pickupToast.classList.add('show')
    clearTimeout(this.pickupTimer)
    this.pickupTimer = setTimeout(() => this.el.pickupToast.classList.remove('show'), 1000)
  }

  toast(text) {
    this.el.toast.textContent = text
    this.el.toast.classList.add('show')
    clearTimeout(this.toastTimer)
    this.toastTimer = setTimeout(() => this.el.toast.classList.remove('show'), 2000)
  }

  showEnd(rows, won) {
    this.el.endTitle.textContent = won ? 'VICTORY!' : 'MATCH OVER'
    this.el.endSub.textContent = won ? 'You ruled the block. Nice shooting!' : 'Good run, block-head. Go again?'
    const me = rows.find(r => r.me)
    this.el.endResults.innerHTML = `
      <div><b>#${rows.findIndex(r => r.me) + 1}</b><span>PLACE</span></div>
      <div><b>${me?.kills || 0}</b><span>KILLS</span></div>
      <div><b>${me?.deaths || 0}</b><span>DEATHS</span></div>
      <div><b>${me?.streak || 0}</b><span>STREAK</span></div>`
    this.show('matchEnd')
  }

  setOnline(count) {
    this.el.menuOnline.textContent = `ONLINE · ${count} PLAYERS`
  }
}

import * as THREE from 'three'
import { createArena, createLobby } from './world.js'
import { createBlockAvatar, createWeaponModel, createMeleeModel, createGrenadeModel, mat } from './avatar.js'
import { Effects } from './effects.js'
import { Sfx } from './audio.js'
import { ArenaNet } from './net.js'
import { UI } from './ui.js'
import {
  WEAPONS, ALL_SKINS, AVATAR_SKINS, GUN_SKINS, MELEE_SKINS, GRENADE_SKINS,
  BOT_NAMES, RESPAWN_TIPS, MATCH_DURATION, KILL_TARGET,
} from './data.js'

const SAVE_KEY = 'blockstrike-save-v1'
const tmpVec = new THREE.Vector3()
const tmpVec2 = new THREE.Vector3()
const raycaster = new THREE.Raycaster()

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)) }
function rand(a, b) { return a + Math.random() * (b - a) }

class Game {
  constructor() {
    this.canvas = document.getElementById('gameCanvas')
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, powerPreference: 'high-performance' })
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6))
    this.renderer.shadowMap.enabled = true
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap
    this.renderer.outputColorSpace = THREE.SRGBColorSpace
    this.renderer.toneMapping = THREE.NoToneMapping

    this.arena = createArena()
    this.effects = new Effects(this.arena.scene)
    this.lobby = createLobby()
    this.camera = new THREE.PerspectiveCamera(72, 1, 0.1, 500)
    this.sfx = new Sfx()

    this.load()
    this.net = new ArenaNet({
      onPeerState: (id, s) => this.onPeerState(id, s),
      onPeerLeave: (id) => this.onPeerLeave(id),
      onRemoteBotHit: (d) => this.onRemoteBotHit(d),
      onBotHp: (d) => this.onBotHp(d),
      onPlayerDamage: (d) => this.onPlayerDamage(d),
      onRemoteKill: (d) => this.onRemoteKill(d),
    })

    this.player = this.makePlayer()
    this.bots = this.makeBots()
    this.remotes = new Map()
    this.projectiles = []
    this.state = 'menu'
    this.matchTime = MATCH_DURATION
    this.matchDuration = MATCH_DURATION
    this.time = 0
    this.keys = {}
    this.touchMove = { x: 0, y: 0 }
    this.touchFire = false
    this.touchAim = false
    this.waitingFireRelease = false
    this.isTouch = window.matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0
    this.suppressPause = false
    this.killSeen = new Set()

    this.ui = new UI(this)
    this.bindEvents()
    this.onResize()
    this.last = performance.now()
    requestAnimationFrame((t) => this.loop(t))
    // Reveal the live 3D lobby once the first frame is ready.
    requestAnimationFrame(() => {
      document.getElementById('loading').classList.add('hidden')
      document.getElementById('menu').classList.remove('hidden')
      this.ui.setOnline(this.net.peerCount + 8)
    })
  }

  /* ---------------- persistence & skins ---------------- */
  load() {
    const fresh = {
      coins: 500,
      owned: {
        avatar: ['classic', 'ninja'], gun: ['factory', 'carbon'],
        melee: ['pipe'], grenade: ['classic'],
      },
      equipped: { avatar: 'classic', gun: 'factory', melee: 'pipe', grenade: 'classic' },
      stats: { kills: 0, wins: 0, best: 0 },
    }
    try {
      const saved = JSON.parse(localStorage.getItem(SAVE_KEY) || 'null')
      if (saved && typeof saved === 'object') {
        fresh.coins = Number.isFinite(saved.coins) ? saved.coins : fresh.coins
        for (const cat of Object.keys(fresh.owned)) {
          if (Array.isArray(saved.owned?.[cat])) fresh.owned[cat] = saved.owned[cat]
          if (saved.equipped?.[cat]) fresh.equipped[cat] = saved.equipped[cat]
        }
        Object.assign(fresh.stats, saved.stats || {})
      }
    } catch (e) { /* ignore corrupt save */ }
    this.coins = fresh.coins
    this.owned = fresh.owned
    this.equipped = fresh.equipped
    this.stats = fresh.stats
    this.save()
  }
  save() {
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify({
        coins: this.coins, owned: this.owned, equipped: this.equipped, stats: this.stats,
      }))
    } catch (e) { /* storage unavailable */ }
  }
  getSkin(cat) {
    const list = ALL_SKINS[cat]
    return list.find(s => s.id === this.equipped[cat]) || list[0]
  }
  isOwned(cat, id) { return this.owned[cat].includes(id) }
  equipSkin(cat, id) {
    if (!this.isOwned(cat, id)) return
    this.equipped[cat] = id
    this.save()
    this.applyLoadout()
  }
  buySkin(cat, skin) {
    if (this.coins < skin.price || this.isOwned(cat, skin.id)) return false
    this.coins -= skin.price
    this.owned[cat].push(skin.id)
    this.equipped[cat] = skin.id
    this.save()
    this.applyLoadout()
    this.sfx.buy()
    this.ui.toast(`Unlocked ${skin.name}!`)
    return true
  }
  applyLoadout() {
    if (!this.player) return
    const skin = this.getSkin('avatar')
    this.player.avatar.setSkin(skin)
    this.rebuildModels(this.player)
    for (const b of this.bots) { /* bots keep their own identities */ }
    this.ui?.refreshLoadout()
    this.ui?.rebuildPreview()
  }

  rebuildModels(ent) {
    if (ent.weaponModels) ent.weaponModels.forEach(m => ent.avatar.weaponAnchor.remove(m))
    ent.weaponModels = WEAPONS.map(w => {
      const m = createWeaponModel(w, this.getSkin('gun'))
      m.visible = false
      ent.avatar.weaponAnchor.add(m)
      return m
    })
    if (ent.meleeModel) ent.avatar.meleeAnchor.remove(ent.meleeModel)
    ent.meleeModel = createMeleeModel(this.getSkin('melee'))
    ent.meleeModel.visible = false
    ent.avatar.meleeAnchor.add(ent.meleeModel)
    if (ent.grenadeModel) ent.avatar.grenadeAnchor.remove(ent.grenadeModel)
    ent.grenadeModel = createGrenadeModel(this.getSkin('grenade'))
    ent.grenadeModel.visible = false
    ent.avatar.grenadeAnchor.add(ent.grenadeModel)
    if (ent.weaponModels[ent.weaponIndex]) ent.weaponModels[ent.weaponIndex].visible = true
    ent.weaponModel = ent.weaponModels[ent.weaponIndex]
  }

  /* ---------------- entity factories ---------------- */
  makePlayer() {
    const skin = this.getSkin('avatar')
    const avatar = createBlockAvatar(skin, { name: 'YOU', nameColor: '#ffd447', showHp: false, owner: 'player' })
    avatar.group.position.set(0, 0, -28)
    this.arena.scene.add(avatar.group)
    const p = {
      id: this.net.id, name: 'YOU', isLocal: true,
      pos: new THREE.Vector3(0, 0, -28), vel: new THREE.Vector3(),
      yaw: 0, pitch: 0, grounded: true,
      health: 100, alive: true, respawnTimer: 0, deaths: 0, kills: 0, streak: 0, highestStreak: 0,
      weaponIndex: 0, ammo: WEAPONS.map(w => w.mag), reserve: WEAPONS.map(w => w.reserve),
      fireCooldown: 0, reloadTimer: 0, reloadWeapon: -1, aiming: false, sprinting: false,
      damageFlash: 0, flashTimer: 0, meleeTimer: 0, meleeCooldown: 0,
      avatar, lastFootstep: 0,
    }
    this.rebuildModels(p)
    return p
  }

  makeBots() {
    const bots = []
    for (let i = 0; i < 8; i++) {
      const skin = AVATAR_SKINS[(i + 2) % AVATAR_SKINS.length]
      const avatar = createBlockAvatar(skin, {
        name: BOT_NAMES[i], nameColor: i % 3 === 0 ? '#ff8a3d' : '#ff6b7a', owner: `bot${i}`,
      })
      const sp = this.arena.spawns[i % this.arena.spawns.length]
      avatar.group.position.copy(sp)
      this.arena.scene.add(avatar.group)
      const weapon = createWeaponModel(WEAPONS[i % 3], GUN_SKINS[i % GUN_SKINS.length])
      weapon.position.set(0.3, 1.16, 0.42)
      avatar.weaponAnchor.add(weapon)
      const bot = {
        id: `bot${i}`, name: BOT_NAMES[i], isBot: true, skin,
        pos: sp.clone(), vel: new THREE.Vector3(), yaw: 0, pitch: 0, grounded: true,
        health: 100, alive: true, respawnTimer: 0, kills: 0, deaths: 0, streak: 0,
        target: null, thinkTimer: rand(0, 0.5), waypoint: null, wpTimer: 0,
        fireCooldown: rand(0, 1), strafe: Math.random() < 0.5 ? 1 : -1,
        avatar, weaponModel: weapon, flashTimer: 0, speed: rand(5.2, 7.2),
        accuracy: rand(0.72, 0.93),
      }
      bots.push(bot)
    }
    return bots
  }

  /* ---------------- input & lifecycle ---------------- */
  bindEvents() {
    window.addEventListener('resize', () => this.onResize())
    document.addEventListener('keydown', (e) => this.onKeyDown(e))
    document.addEventListener('keyup', (e) => this.onKeyUp(e))
    document.addEventListener('mousemove', (e) => {
      if (document.pointerLockElement === this.canvas) this.onMouseMove(e.movementX, e.movementY)
    })
    document.addEventListener('mouseup', (e) => { if (e.button === 0) this.mouseDown = false; if (e.button === 2) this.mouseAim = false })
    this.canvas.addEventListener('mousedown', (e) => {
      if (this.state !== 'playing') return
      if (document.pointerLockElement !== this.canvas && !this.isTouch) this.canvas.requestPointerLock?.()
      if (e.button === 0) this.mouseDown = true
      if (e.button === 2) this.mouseAim = true
    })
    this.canvas.addEventListener('contextmenu', e => e.preventDefault())
    this.canvas.addEventListener('wheel', (e) => {
      if (this.state !== 'playing') return
      e.preventDefault()
      this.switchWeapon(this.player.weaponIndex + (e.deltaY > 0 ? 1 : -1))
    }, { passive: false })
    document.addEventListener('pointerlockchange', () => {
      if (document.pointerLockElement !== this.canvas && this.state === 'playing' && !this.suppressPause && !this.isTouch) this.pause()
    })
    // Drag the 3D lobby camera with the mouse.
    let dragging = false, lx = 0
    this.canvas.addEventListener('pointerdown', e => { if (this.state === 'menu') { dragging = true; lx = e.clientX } })
    window.addEventListener('pointerup', () => { dragging = false })
    window.addEventListener('pointermove', e => {
      if (dragging && this.state === 'menu') { this.lobby.rotate(e.clientX - lx); lx = e.clientX }
    })
  }

  onResize() {
    const w = window.innerWidth, h = window.innerHeight
    this.renderer.setSize(w, h, false)
    this.camera.aspect = w / h
    this.camera.updateProjectionMatrix()
    this.lobby.camera.aspect = w / h
    this.lobby.camera.updateProjectionMatrix()
  }

  onMouseMove(dx, dy) {
    if (this.state !== 'playing') return
    this.player.yaw += dx * 0.0022
    this.player.pitch = clamp(this.player.pitch - dy * 0.0022, -1.45, 1.45)
  }

  onKeyDown(e) {
    const k = e.key.toLowerCase()
    this.keys[k] = true
    if (k === 'tab') {
      e.preventDefault()
      if (this.state === 'playing') this.ui.el.scoreboard.classList.remove('hidden')
    }
    if (e.key === 'Escape') {
      if (!this.ui.el.customize.classList.contains('hidden')) { this.ui.closeCustomize(); return }
      if (!this.ui.el.how.classList.contains('hidden')) { this.ui.el.how.classList.add('hidden'); return }
      if (this.state === 'playing') this.pause()
      else if (this.state === 'paused') this.resume()
      return
    }
    if (this.state !== 'playing') return
    if (k === ' ') { e.preventDefault(); this.jump() }
    if (k === 'r') this.reload()
    if (k === 'v') this.melee()
    if (k === 'g') this.throwGrenade()
    if (k === 'b') this.openCustomizeInGame()
    if (['1', '2', '3', '4'].includes(k)) this.switchWeapon(parseInt(k, 10) - 1)
  }
  onKeyUp(e) {
    const k = e.key.toLowerCase()
    this.keys[k] = false
    if (k === 'tab') this.ui.el.scoreboard.classList.add('hidden')
  }

  openCustomizeInGame() {
    this.suppressPause = true
    document.exitPointerLock?.()
    this.ui.openCustomize('avatar')
  }

  startMatch() {
    this.sfx.init()
    this.sfx.click()
    this.matchTime = MATCH_DURATION
    this.matchDuration = MATCH_DURATION
    this.killSeen.clear()
    this.projectiles.forEach(p => this.arena.scene.remove(p.mesh))
    this.projectiles = []
    const resetEntity = (e, idx) => {
      const sp = this.arena.spawns[idx % this.arena.spawns.length]
      e.pos.copy(sp); e.vel.set(0, 0, 0)
      e.health = 100; e.alive = true; e.respawnTimer = 0
      e.kills = 0; e.deaths = 0; e.streak = 0
      e.avatar.setDead(false)
      if (e.isLocal) {
        e.ammo = WEAPONS.map(w => w.mag)
        e.reserve = WEAPONS.map(w => w.reserve)
        e.reloadTimer = 0
        e.weaponIndex = 0
        e.yaw = Math.atan2(-sp.x, -sp.z)
        e.pitch = 0
      }
    }
    resetEntity(this.player, 4)
    this.bots.forEach((b, i) => resetEntity(b, i))
    this.ui.el.customize.classList.add('hidden')
    this.ui.el.how.classList.add('hidden')
    this.ui.show('hud')
    this.ui.el.touch.classList.toggle('hidden', !this.isTouch)
    this.state = 'playing'
    this.suppressPause = false
    this.last = performance.now()
    if (!this.isTouch) this.canvas.requestPointerLock?.()
  }

  pause() {
    if (this.state !== 'playing') return
    this.state = 'paused'
    this.ui.show('pause')
    this.ui.el.touch.classList.add('hidden')
    document.exitPointerLock?.()
    this.mouseDown = false; this.mouseAim = false
  }
  resume() {
    if (this.state !== 'paused') return
    this.ui.show('hud')
    this.ui.el.touch.classList.toggle('hidden', !this.isTouch)
    this.state = 'playing'
    this.last = performance.now()
    if (!this.isTouch) this.canvas.requestPointerLock?.()
  }
  quitToMenu() {
    this.state = 'menu'
    this.ui.show('menu')
    this.ui.el.touch.classList.add('hidden')
    this.ui.el.customize.classList.add('hidden')
    this.ui.refreshLoadout()
    this.ui.setOnline(this.net.peerCount + 8)
    document.exitPointerLock?.()
  }
  endMatch() {
    if (this.state !== 'playing') return
    this.state = 'end'
    const rows = this.scoreboardEntries()
    const won = this.player.kills >= KILL_TARGET || (rows[0]?.me && rows[0].kills >= this.player.kills)
    if (won) { this.stats.wins++; this.coins += 200; this.save() }
    this.ui.showEnd(rows, won)
    this.ui.el.touch.classList.add('hidden')
    document.exitPointerLock?.()
    this.sfx.kill()
  }

  /* ---------------- movement ---------------- */
  collideAt(x, y, z, radius = 0.42, height = 1.75) {
    tmpVec.set(x, y, z)
    return this.arena.collide(tmpVec, radius, height)
  }

  moveEntity(e, dt, wx, wz, speed) {
    const len = Math.hypot(wx, wz)
    if (len > 0) { wx /= len; wz /= len }
    const targetVX = wx * speed, targetVZ = wz * speed
    const accel = 1 - Math.exp(-dt * (len > 0 ? 14 : 10))
    e.vel.x += (targetVX - e.vel.x) * accel
    e.vel.z += (targetVZ - e.vel.z) * accel
    e.vel.y -= 24 * dt
    if (e.vel.y < -32) e.vel.y = -32

    const nx = e.pos.x + e.vel.x * dt
    if (!this.collideAt(nx, e.pos.y, e.pos.z)) e.pos.x = nx
    else e.vel.x = 0
    const nz = e.pos.z + e.vel.z * dt
    if (!this.collideAt(e.pos.x, e.pos.y, nz)) e.pos.z = nz
    else e.vel.z = 0
    const ny = e.pos.y + e.vel.y * dt
    if (this.collideAt(e.pos.x, ny, e.pos.z)) {
      if (e.vel.y < 0) e.grounded = true
      e.vel.y = 0
    } else {
      e.pos.y = ny
      if (e.pos.y <= 0) { e.pos.y = 0; e.grounded = true; if (e.vel.y < -4) e.landed = true; e.vel.y = 0 }
      else e.grounded = false
    }
    this.arena.clamp(e.pos)
  }

  jump() {
    const p = this.player
    if (!p.alive || !p.grounded) return
    p.vel.y = 9.2
    p.grounded = false
    this.sfx.jump()
  }

  /* ---------------- weapons ---------------- */
  switchWeapon(idx) {
    const p = this.player
    idx = (idx + WEAPONS.length) % WEAPONS.length
    if (idx === p.weaponIndex || p.reloadTimer > 0) return
    if (p.weaponModels[p.weaponIndex]) p.weaponModels[p.weaponIndex].visible = false
    p.weaponIndex = idx
    if (p.weaponModels[idx]) p.weaponModels[idx].visible = true
    p.weaponModel = p.weaponModels[idx]
    p.fireCooldown = Math.max(p.fireCooldown, 0.18)
    p.aiming = false
    this.sfx.click()
    this.ui.updateWeaponSlots()
  }
  reload() {
    const p = this.player
    const w = WEAPONS[p.weaponIndex]
    if (!p.alive || p.reloadTimer > 0 || p.ammo[p.weaponIndex] >= w.mag || p.reserve[p.weaponIndex] <= 0) return
    p.reloadTimer = w.reload
    p.reloadWeapon = p.weaponIndex
    this.sfx.reload()
  }

  melee() {
    const p = this.player
    if (!p.alive || p.meleeCooldown > 0) return
    p.meleeTimer = 0.32
    p.meleeCooldown = 0.62
    p.meleeModel.visible = true
    this.sfx.swing()
    const dir = this.aimDirection()
    for (const t of [...this.bots, ...this.remotes.values()]) {
      if (!t.alive) continue
      const to = tmpVec.copy(t.pos).sub(p.pos).setY(0)
      const d = to.length()
      if (d > 2.8) continue
      to.normalize()
      if (to.dot(dir.setY(0).normalize()) > 0.45) {
        this.dealDamage(t, 42, p, false, 'MELEE', 'melee')
      }
    }
  }

  throwGrenade() {
    const p = this.player
    if (!p.alive || (p.grenadeCooldown || 0) > 0) return
    p.grenadeCooldown = 1.4
    p.grenadeModel.visible = false
    const dir = this.aimDirection()
    const mesh = createGrenadeModel(this.getSkin('grenade'))
    mesh.scale.setScalar(1.1)
    const pos = p.pos.clone().add(new THREE.Vector3(0, 1.4, 0)).addScaledVector(dir, 0.7)
    mesh.position.copy(pos)
    this.arena.scene.add(mesh)
    this.projectiles.push({
      mesh, pos, vel: dir.clone().multiplyScalar(19).add(new THREE.Vector3(0, 7, 0)),
      fuse: 2.1, owner: p,
    })
    this.sfx.swing()
  }

  aimDirection() {
    const p = this.player
    return new THREE.Vector3(
      Math.sin(p.yaw) * Math.cos(p.pitch),
      Math.sin(p.pitch),
      Math.cos(p.yaw) * Math.cos(p.pitch),
    ).normalize()
  }

  shoot() {
    const p = this.player
    const w = WEAPONS[p.weaponIndex]
    if (!p.alive || p.reloadTimer > 0 || p.fireCooldown > 0) return
    if (p.ammo[p.weaponIndex] <= 0) { this.reload(); return }
    p.ammo[p.weaponIndex]--
    p.fireCooldown = w.rate

    const model = p.weaponModel
    const muzzle = model.userData.muzzle.clone()
    model.updateWorldMatrix(true, false)
    model.localToWorld(muzzle)
    const camDir = new THREE.Vector3()
    this.camera.getWorldDirection(camDir)
    const camPos = this.camera.position.clone()
    const targets = []
    for (const b of this.bots) if (b.alive) targets.push(...b.avatar.hitMeshes)
    for (const r of this.remotes.values()) if (r.alive && r.avatar) targets.push(...r.avatar.hitMeshes)
    targets.push(...this.arena.solidMeshes)
    raycaster.far = w.range

    let endPoint = camPos.clone().addScaledVector(camDir, w.range)
    let hitAny = false
    let headAny = false
    for (let i = 0; i < w.pellets; i++) {
      const spread = p.aiming ? w.adsSpread : w.spread
      const dir = camDir.clone()
      dir.x += rand(-spread, spread)
      dir.y += rand(-spread, spread)
      dir.z += rand(-spread, spread)
      dir.normalize()
      raycaster.set(camPos, dir)
      const hits = raycaster.intersectObjects(targets, false)
      const hit = hits[0]
      if (!hit) { this.effects.tracer(muzzle, endPoint, this.getSkin('gun').glow, 0.035, 0.07); continue }
      endPoint = hit.point.clone()
      const ud = hit.object.userData || {}
      if (ud.owner) {
        const victim = this.findEntity(ud.owner)
        if (victim) {
          const head = ud.hitZone === 'head'
          const dist = hit.distance
          const falloff = clamp(1 - Math.max(0, dist - w.range * 0.55) / (w.range * 0.6), 0.45, 1)
          const dmg = Math.round(w.damage * (head ? w.headMult : 1) * falloff)
          this.dealDamage(victim, dmg, p, head, w.name, 'gun')
          this.effects.blood(hit.point)
          this.effects.damageNumber(hit.point, dmg, head)
          hitAny = true; headAny = headAny || head
        }
      } else {
        this.effects.impact(hit.point, 0xffd447, 5)
      }
      this.effects.tracer(muzzle, hit.point, this.getSkin('gun').glow, 0.035, 0.07)
    }
    model.userData.flash.visible = true
    p.flashTimer = 0.05
    p.pitch = clamp(p.pitch + w.recoil * (p.aiming ? 0.55 : 1) * rand(0.8, 1.2), -1.45, 1.45)
    p.yaw += rand(-w.recoil, w.recoil) * 0.3
    this.sfx.shoot(w.id)
    if (hitAny || headAny) {
      this.ui.showHit(headAny)
      this.sfx[headAny ? 'headshot' : 'hit']()
    }
    this.ui.updateHud(this)
  }

  findEntity(id) {
    if (id === this.player.id || id === 'player') return this.player
    const bot = this.bots.find(b => b.id === id)
    if (bot) return bot
    return this.remotes.get(id)
  }

  /* ---------------- damage & kills ---------------- */
  dealDamage(target, amount, source, head, weapon, kind = 'gun') {
    if (!target || !target.alive || amount <= 0) return
    const wasAlive = target.alive
    target.health -= amount
    if (target.isLocal) {
      target.damageFlash = 1
      this.sfx.hurt()
      if (!this.net.host && source && source !== target && source.id !== this.player.id) {
        // host already knows through its own bots; local view still flashes.
      }
    }
    if (target.isBot) {
      target.avatar.setHealth(target.health)
      if (this.net.host) this.net.send('botHp', { id: target.id, hp: target.health })
      else if (source === this.player && kind === 'gun') {
        this.net.send('botHit', { target: target.id, amount, head, shooter: this.player.id, weapon })
      }
    }
    if (target.health <= 0 && wasAlive) {
      this.registerKill(target, source, weapon, head)
    }
  }

  registerKill(victim, killer, weapon, head) {
    victim.health = 0
    victim.alive = false
    victim.deaths = (victim.deaths || 0) + 1
    victim.respawnTimer = victim.isLocal ? 3 : rand(2.5, 4)
    victim.avatar.setDead(true)
    victim.vel.set(0, 0, 0)
    const killerName = killer?.name || 'The Arena'
    if (killer && killer !== victim) {
      killer.kills = (killer.kills || 0) + 1
      killer.streak = (killer.streak || 0) + 1
      killer.highestStreak = Math.max(killer.highestStreak || 0, killer.streak)
      if (killer.isLocal) {
        const coins = 40 + (head ? 20 : 0) + Math.min(40, killer.streak * 5)
        this.coins += coins
        this.stats.kills++
        this.stats.best = Math.max(this.stats.best, killer.streak)
        this.save()
        this.ui.showKillBanner(head ? 'HEADSHOT!' : killerName, coins)
        this.sfx.kill()
        this.ui.toast(`+${coins} coins · ${killer.streak} kill streak`)
      }
    }
    this.ui.addKill(killerName, victim.name || 'Player', weapon, head)
    if (victim.isBot && this.net.host) {
      this.net.send('botHp', { id: victim.id, hp: 0 })
      this.net.send('kill', { killer: killerName, victim: victim.name, weapon, head })
    }
    if (victim.isLocal) this.sfx.hurt()
    if (killer?.isLocal && this.player.kills >= KILL_TARGET) this.endMatch()
  }

  respawn(e, idx) {
    const sp = this.arena.spawns[Math.floor(rand(0, this.arena.spawns.length - 1))]
    e.pos.copy(sp)
    e.pos.y = sp.y || 0
    e.vel.set(0, 0, 0)
    e.health = 100
    e.alive = true
    e.streak = 0
    e.avatar.setDead(false)
    e.avatar.setHealth(100)
    if (e.isLocal) {
      e.ammo = WEAPONS.map(w => w.mag)
      e.reloadTimer = 0
      e.damageFlash = 0
      e.yaw = Math.atan2(-sp.x, -sp.z)
      this.ui.el.respawnTip.textContent = RESPAWN_TIPS[Math.floor(rand(0, RESPAWN_TIPS.length))]
    }
  }

  /* ---------------- net handlers ---------------- */
  onPeerState(id, s) {
    if (!s || !Array.isArray(s.p)) return
    let r = this.remotes.get(id)
    if (!r) {
      const skin = AVATAR_SKINS.find(a => a.id === s.skin) || AVATAR_SKINS[0]
      const avatar = createBlockAvatar(skin, { name: s.name || 'PLAYER', nameColor: '#4aa8ff', owner: id })
      this.arena.scene.add(avatar.group)
      r = { id, name: s.name || 'PLAYER', avatar, pos: new THREE.Vector3(...s.p), alive: true, health: 100, kills: 0, deaths: 0, streak: 0, yaw: 0, weaponIndex: s.weapon || 0 }
      this.remotes.set(id, r)
      this.ui.toast(`${r.name} joined the arena!`)
      if (this.player.weaponModels[s.weapon || 0]) {
        const m = createWeaponModel(WEAPONS[s.weapon || 0], GUN_SKINS[0])
        m.position.set(0.3, 1.16, 0.42)
        avatar.weaponAnchor.add(m)
      }
    }
    r.targetPos = new THREE.Vector3(...s.p)
    r.yaw = s.yaw || 0
    r.alive = s.alive !== false
    r.health = s.hp ?? r.health
    r.avatar.setDead(!r.alive)
    r.avatar.setHealth(r.health)
    this.ui.setOnline(this.net.peerCount + 8)
  }
  onPeerLeave(id) {
    const r = this.remotes.get(id)
    if (r) { this.arena.scene.remove(r.avatar.group); this.remotes.delete(id) }
    this.ui.setOnline(this.net.peerCount + 8)
  }
  onRemoteBotHit(d) {
    if (!this.net.host) return
    const bot = this.bots.find(b => b.id === d.target)
    if (!bot || !bot.alive) return
    const source = d.shooter === this.player.id ? this.player : this.remotes.get(d.shooter) || { name: 'PLAYER', id: d.shooter }
    this.dealDamage(bot, d.amount, source, d.head, d.weapon || 'GUN', 'net')
  }
  onBotHp(d) {
    const bot = this.bots.find(b => b.id === d.id)
    if (!bot) return
    bot.health = d.hp
    bot.avatar.setHealth(d.hp)
    if (d.hp <= 0 && bot.alive) {
      bot.alive = false
      bot.deaths++
      bot.respawnTimer = rand(2.5, 4)
      bot.avatar.setDead(true)
    }
  }
  onPlayerDamage(d) {
    if (d.target !== this.player.id || !this.player.alive) return
    const source = this.bots.find(b => b.name === d.from) || this.remotes.get(d.from)
    this.dealDamage(this.player, d.amount, source || { name: d.from || 'PLAYER' }, d.head, d.weapon || 'GUN', 'net')
  }
  onRemoteKill(d) {
    const key = `${d.killer}|${d.victim}|${Math.round(this.time)}`
    if (this.killSeen.has(key)) return
    this.killSeen.add(key)
    this.ui.addKill(d.killer, d.victim, d.weapon, d.head)
  }

  /* ---------------- bots ---------------- */
  updateBots(dt) {
    for (const b of this.bots) {
      if (!b.alive) {
        b.respawnTimer -= dt
        if (b.respawnTimer <= 0) this.respawn(b)
        continue
      }
      b.fireCooldown -= dt
      b.thinkTimer -= dt
      b.wpTimer -= dt
      b.flashTimer = Math.max(0, b.flashTimer - dt)
      b.weaponModel.userData.flash.visible = b.flashTimer > 0

      // select target
      if (b.thinkTimer <= 0) {
        b.thinkTimer = rand(0.35, 0.7)
        const candidates = [this.player, ...this.remotes.values(), ...this.bots]
        let best = null, bestD = 42
        for (const c of candidates) {
          if (c === b || !c.alive || (c.isBot && !this.net.host)) continue
          const d = b.pos.distanceTo(c.pos)
          if (d < bestD && this.hasLineOfSight(b.pos, c.pos)) { best = c; bestD = d }
        }
        b.target = best
        if (!b.waypoint || b.wpTimer <= 0 || b.pos.distanceTo(b.waypoint) < 2.5) {
          b.waypoint = this.arena.waypoints[Math.floor(rand(0, this.arena.waypoints.length))].clone()
          b.wpTimer = rand(5, 10)
        }
      }

      let wx = 0, wz = 0, speed = b.speed
      if (b.target) {
        const to = tmpVec.copy(b.target.pos).sub(b.pos)
        const dist = to.length()
        const desiredYaw = Math.atan2(to.x, to.z)
        b.yaw = this.angleLerp(b.yaw, desiredYaw, 1 - Math.exp(-dt * 7))
        const dy = (b.target.pos.y + 1.3) - (b.pos.y + 1.5)
        b.pitch = this.angleLerp(b.pitch, Math.atan2(dy, Math.max(1, dist)), 1 - Math.exp(-dt * 6))
        const fwd = tmpVec2.set(Math.sin(b.yaw), 0, Math.cos(b.yaw))
        if (dist > 17) { wx = fwd.x; wz = fwd.z }
        else if (dist < 9) { wx = -fwd.x; wz = -fwd.z }
        else {
          wx = fwd.z * b.strafe; wz = -fwd.x * b.strafe
          if (Math.random() < dt * 0.4) b.strafe *= -1
        }
        if (dist < 38 && b.fireCooldown <= 0 && this.hasLineOfSight(b.pos, b.target.pos)) {
          this.botShoot(b, b.target, dist)
          b.fireCooldown = rand(0.16, 0.42)
        }
      } else if (b.waypoint) {
        const to = tmpVec.copy(b.waypoint).sub(b.pos)
        const desiredYaw = Math.atan2(to.x, to.z)
        b.yaw = this.angleLerp(b.yaw, desiredYaw, 1 - Math.exp(-dt * 4))
        wx = Math.sin(b.yaw); wz = Math.cos(b.yaw)
        speed *= 0.75
      }
      this.moveEntity(b, dt, wx, wz, speed)
      b.avatar.group.position.copy(b.pos)
      b.avatar.group.rotation.y = b.yaw
      b.avatar.head.rotation.x = -b.pitch * 0.6
      b.avatar.animate(dt, Math.hypot(b.vel.x, b.vel.z), !b.grounded, false)

      // health pickup
      if (b.health < 70) {
        for (const pk of this.arena.pickups) {
          if (pk.active && b.pos.distanceTo(pk.pos) < 3.5) {
            this.arena.takePickup(b.pos)
            b.health = Math.min(100, b.health + 40)
            b.avatar.setHealth(b.health)
            this.effects.impact(pk.pos, 0x5ce1b9, 5)
          }
        }
      }
    }
  }

  angleLerp(a, b, t) {
    let d = ((b - a + Math.PI) % (Math.PI * 2)) - Math.PI
    if (d < -Math.PI) d += Math.PI * 2
    return a + d * t
  }

  hasLineOfSight(from, to) {
    const a = from.clone().add(new THREE.Vector3(0, 1.5, 0))
    const b = to.clone().add(new THREE.Vector3(0, 1.3, 0))
    const dir = b.clone().sub(a)
    const dist = dir.length()
    raycaster.set(a, dir.normalize())
    raycaster.far = dist - 0.6
    const hits = raycaster.intersectObjects(this.arena.solidMeshes, false)
    raycaster.far = 300
    return hits.length === 0
  }

  botShoot(bot, target, dist) {
    const from = bot.pos.clone().add(new THREE.Vector3(0, 1.5, 0))
    const aim = target.pos.clone().add(new THREE.Vector3(0, 1.3, 0))
    const dir = aim.sub(from).normalize()
    const spread = (1 - bot.accuracy) * 1.8 + dist * 0.002
    dir.x += rand(-spread, spread); dir.y += rand(-spread, spread); dir.z += rand(-spread, spread)
    dir.normalize()
    raycaster.set(from, dir)
    raycaster.far = 60
    const targets = []
    if (target.isLocal || (target !== this.player && this.net.host)) {
      // Only the host decides damage for remote humans; local player takes its own.
      if (target.isLocal) targets.push(...this.player.avatar.hitMeshes)
    } else if (target.isBot && this.net.host) targets.push(...target.avatar.hitMeshes)
    if (targets.length === 0) targets.push(...this.arena.solidMeshes)
    const hits = raycaster.intersectObjects(targets.concat(this.arena.solidMeshes), false)
    const hit = hits[0]
    const end = hit ? hit.point : from.clone().addScaledVector(dir, 60)
    bot.weaponModel.updateWorldMatrix(true, false)
    const muzzle = bot.weaponModel.localToWorld(bot.weaponModel.userData.muzzle.clone())
    this.effects.tracer(muzzle, end, 0xff8a3d, 0.04, 0.08)
    bot.flashTimer = 0.05
    if (hit?.object.userData?.owner) {
      const dmg = Math.round(rand(8, 13))
      const head = hit.object.userData.hitZone === 'head'
      if (target.isLocal) {
        this.dealDamage(this.player, dmg, bot, head, 'ENEMY GUN', 'bot')
      } else if (this.net.host && target.id && target !== this.player) {
        this.net.send('playerDamage', { target: target.id, from: bot.name, amount: dmg, head, weapon: 'ENEMY GUN' })
      } else if (target.isBot && this.net.host) {
        this.dealDamage(target, dmg, bot, head, 'ENEMY GUN', 'bot')
      }
    }
    raycaster.far = 300
  }

  /* ---------------- projectiles ---------------- */
  updateProjectiles(dt) {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const g = this.projectiles[i]
      g.fuse -= dt
      g.vel.y -= 20 * dt
      const next = g.pos.clone().addScaledVector(g.vel, dt)
      const blocked = this.collideAt(next.x, next.y, next.z, 0.15, 0.2) || next.y <= 0.12
      if (blocked) {
        g.vel.multiplyScalar(0.35)
        g.vel.y = Math.abs(g.vel.y) * 0.4
      } else g.pos.copy(next)
      g.mesh.position.copy(g.pos)
      g.mesh.rotation.x += dt * 12
      if (g.fuse <= 0) {
        this.effects.explosion(g.pos, 4.5)
        this.sfx.shoot('shotgun')
        for (const t of [this.player, ...this.bots, ...this.remotes.values()]) {
          if (!t.alive) continue
          const d = t.pos.distanceTo(g.pos)
          if (d < 5.2) {
            const dmg = Math.round(95 * (1 - d / 6))
            if (t.isLocal || t.isBot && this.net.host) this.dealDamage(t, dmg, g.owner, false, 'GRENADE', 'explosion')
            else if (t.id && t.isBot === undefined) this.net.send('playerDamage', { target: t.id, from: g.owner.name, amount: dmg, head: false, weapon: 'GRENADE' })
          }
        }
        this.arena.scene.remove(g.mesh)
        this.projectiles.splice(i, 1)
      }
    }
  }

  /* ---------------- camera & update ---------------- */
  updateCamera(dt) {
    const p = this.player
    const dir = this.aimDirection()
    const target = new THREE.Vector3(p.pos.x, p.pos.y + 1.5, p.pos.z)
    const right = new THREE.Vector3(Math.cos(p.yaw), 0, -Math.sin(p.yaw))
    const dist = p.aiming ? 2.9 : 5.0
    const side = p.aiming ? 0.5 : 0.95
    const height = p.aiming ? 0.3 : 0.85
    const desired = target.clone().addScaledVector(dir, -dist).addScaledVector(right, side).add(new THREE.Vector3(0, height, 0))
    // pull camera in when a wall is behind the player
    const camDir = desired.clone().sub(target)
    const camLen = camDir.length()
    camDir.normalize()
    for (let i = 1; i <= 10; i++) {
      const test = target.clone().addScaledVector(camDir, camLen * i / 10)
      if (this.collideAt(test.x, test.y, test.z, 0.2, 0.2)) {
        desired.copy(target).addScaledVector(camDir, Math.max(0.6, camLen * (i - 1) / 10 - 0.2))
        break
      }
    }
    this.camera.position.lerp(desired, 1 - Math.exp(-dt * 18))
    const look = target.clone().addScaledVector(dir, p.aiming ? 40 : 12)
    this.camera.lookAt(look)
    const speed = Math.hypot(p.vel.x, p.vel.z)
    const baseFov = 72 - (p.aiming ? 72 * (1 - WEAPONS[p.weaponIndex].adsZoom) : 0)
    const targetFov = baseFov + Math.min(5, speed * 0.5)
    this.camera.fov += (targetFov - this.camera.fov) * (1 - Math.exp(-dt * 10))
    this.camera.updateProjectionMatrix()
  }

  update(dt) {
    this.matchTime -= dt
    if (this.matchTime <= 0 || this.player.kills >= KILL_TARGET) { this.endMatch(); return }
    const p = this.player
    p.fireCooldown = Math.max(0, p.fireCooldown - dt)
    p.meleeCooldown = Math.max(0, p.meleeCooldown - dt)
    p.grenadeCooldown = Math.max(0, (p.grenadeCooldown || 0) - dt)
    p.damageFlash = Math.max(0, p.damageFlash - dt * 1.8)
    p.flashTimer = Math.max(0, p.flashTimer - dt)
    if (p.weaponModel) p.weaponModel.userData.flash.visible = p.flashTimer > 0
    p.meleeTimer = Math.max(0, p.meleeTimer - dt)
    if (p.meleeModel) {
      p.meleeModel.visible = p.meleeTimer > 0
      p.meleeModel.rotation.z = -0.5 + Math.sin((1 - p.meleeTimer / 0.32) * Math.PI) * 1.8
    }
    if (p.grenadeCooldown > 1.0 && p.grenadeModel) p.grenadeModel.visible = true

    if (!p.alive) {
      p.respawnTimer -= dt
      if (p.respawnTimer <= 0) this.respawn(p)
    } else {
      // Movement input
      const f = (this.keys['w'] ? 1 : 0) - (this.keys['s'] ? 1 : 0) + (-this.touchMove.y)
      const s = (this.keys['d'] ? 1 : 0) - (this.keys['a'] ? 1 : 0) + this.touchMove.x
      p.aiming = !!(this.mouseAim || this.touchAim)
      p.sprinting = !!(this.keys['shift'] && f > 0 && !p.aiming)
      const speed = p.aiming ? 4.6 : p.sprinting ? 11.2 : 7.4
      const wx = Math.sin(p.yaw) * f + Math.cos(p.yaw) * s
      const wz = Math.cos(p.yaw) * f - Math.sin(p.yaw) * s
      this.moveEntity(p, dt, wx, wz, speed)
      if (p.grounded && p.landed) { this.sfx.land(); p.landed = false }
      p.avatar.group.position.copy(p.pos)
      p.avatar.group.rotation.y = p.yaw
      p.avatar.head.rotation.x = -p.pitch * 0.5
      p.avatar.animate(dt, Math.hypot(p.vel.x, p.vel.z), !p.grounded, p.aiming)

      // Reload completion
      if (p.reloadTimer > 0) {
        p.reloadTimer -= dt
        if (p.reloadTimer <= 0) {
          const w = WEAPONS[p.reloadWeapon]
          const need = w.mag - p.ammo[p.reloadWeapon]
          const take = Math.min(need, p.reserve[p.reloadWeapon])
          p.ammo[p.reloadWeapon] += take
          p.reserve[p.reloadWeapon] -= take
          p.reloadTimer = 0
        }
      }
      const wantFire = this.mouseDown || this.touchFire
      const w = WEAPONS[p.weaponIndex]
      if (wantFire && (w.auto || !this.waitingFireRelease)) {
        this.shoot()
        if (!w.auto) this.waitingFireRelease = true
      }
      if (!wantFire) this.waitingFireRelease = false

      if (this.arena.takePickup(p.pos)) {
        p.health = Math.min(100, p.health + 35)
        p.avatar.setHealth(p.health)
        this.sfx.pickup()
        this.ui.showPickup('+35 HEALTH')
      }
    }

    this.updateBots(dt)
    this.updateProjectiles(dt)
    this.updateCamera(dt)
    this.arena.update(dt, this.time)
    this.effects.update(dt)
    this.net.update()
    this.net.broadcastPlayerState({
      p: [p.pos.x, p.pos.y, p.pos.z], yaw: p.yaw, hp: Math.round(p.health),
      alive: p.alive, skin: this.equipped.avatar, weapon: p.weaponIndex, name: 'PLAYER' + this.net.id.slice(0, 3),
    })
    this.ui.updateHud(this)
  }

  scoreboardEntries() {
    const all = [
      { name: 'YOU', me: true, kills: this.player.kills, deaths: this.player.deaths, streak: this.player.streak },
      ...this.bots.map(b => ({ name: b.name, kills: b.kills, deaths: b.deaths, streak: b.streak })),
      ...[...this.remotes.values()].map(r => ({ name: r.name, kills: r.kills, deaths: r.deaths, streak: r.streak })),
    ]
    return all.sort((a, b) => b.kills - a.kills || a.deaths - b.deaths)
  }

  loop(now) {
    const dt = Math.min(0.05, (now - this.last) / 1000)
    this.last = now
    this.time += dt
    if (this.state === 'menu') {
      this.lobby.update(dt, this.time)
      this.renderer.render(this.lobby.scene, this.lobby.camera)
    } else {
      if (this.state === 'playing') this.update(dt)
      this.renderer.render(this.arena.scene, this.camera)
    }
    this.ui.updatePreview(dt, this.time)
    requestAnimationFrame((t) => this.loop(t))
  }
}

